insert into public.kb_docs (source, source_ref, title, question, answer, category, internal_only, first_line) values
('doc', 'servos-features-2026-11-15', 'Location settings', 'Location settings: does ServOS do this and where is it? (Venue)', 'Venue name, address, timezone, currency, New day starts at, service periods, opening hours and closed dates, online slug, images on POS buttons, customer details level, fire to kitchen minutes. Where to find it: Back Office, Settings, Location settings.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'Currency per venue', 'Currency per venue: does ServOS do this and where is it? (Venue)', 'GBP, USD and EUR with the right symbol everywhere; refunds in the paid currency. Where to find it: Location settings, Location currency.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'Appearance (theming)', 'Appearance (theming): does ServOS do this and where is it? (Venue)', 'Brand colour, logo, header photo and style, logo shape, display name and light, dark or auto scheme for online, QR, catering, loyalty portal and gift pages. Where to find it: Back Office, Channels, Appearance.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'Logo for products with no photo', 'Logo for products with no photo: does ServOS do this and where is it? (Venue)', 'Products without a photo show the venue logo on the till, kiosk, online and menu boards. Where to find it: Appearance, Brand basics.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'Every time zone on Add location', 'Every time zone on Add location: does ServOS do this and where is it? (Venue)', 'Add location and the sites page offer every time zone, US Eastern to Hawaii first, then every region. A time zone changed in Location settings now reaches payroll, card payments, bookings, the Manager app and ezCater, and is checked again every night. Where to find it: Company admin, Add location; Location settings.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'New site picks its currency', 'New site picks its currency: does ServOS do this and where is it? (Venue)', 'The currency box starts blank and must be picked before a site is saved, like the time zone, so a US site is never saved in pounds. Where to find it: Add location.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'US venues in US words', 'US venues in US words: does ServOS do this and where is it? (Venue)', 'Dates read Nov 3, 2026 and times 2:05 PM on every screen, week starts on the venue''s work week day, Tax or Sales tax never VAT, $ never US$, US phone and ZIP examples, pickup not collection, your delivery apps instead of Deliveroo and Just Eat, FDA temperatures and the 9 US allergens. Every screen follows the venue being worked on, never the one the browser read last. UK venues read exactly as before. Where to find it: Every screen at a US venue.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'Icons, not emoji', 'Icons, not emoji: does ServOS do this and where is it? (Venue)', 'Every picture emoji in Back Office, on the till, kitchen screens, the phone till, the apps and every customer screen is now a ServOS line icon in the venue''s own colours. Icons a venue saved draw as the matching line icon, nothing saved changes, kiosk language buttons read EN, ES, FR and ZH. A test fails if an emoji comes back. Where to find it: Everywhere.', 'Set up: venue, menu, devices, staff / Venue', false, false),
('doc', 'servos-features-2026-11-15', 'Items and modifiers', 'Items and modifiers: does ServOS do this and where is it? (Menu)', 'Category tree, drag to reorder, item editor with price, POS name, item code, sizes, modifiers, price per channel, allergens, dietary tags and an archive. Where to find it: Back Office, Menu, Items & modifiers.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Modifier groups and instruction groups', 'Modifier groups and instruction groups: does ServOS do this and where is it? (Menu)', 'Pick one, pick many or pick with quantity; put one group on many products and edits follow to every copy. Where to find it: Menu, Modifier groups tab.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Menus and timed menus', 'Menus and timed menus: does ServOS do this and where is it? (Menu)', 'Several menus; timed menus switch by schedule on the venue clock and the default menu takes over outside the window; one resolver shared by till, kiosk, phone, online and boards. Where to find it: Menu, Menus; Back Office, Device profiles, Menu.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Price rules', 'Price rules: does ServOS do this and where is it? (Menu)', 'One price resolver with base price, a price per order type (dine in, takeaway, collection, delivery, drive thru) and per menu pricing tiers; tiles and cart always agree. Where to find it: Menu, item pricing and Pricing tab.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Sharing: Local, Shared, Global', 'Sharing: Local, Shared, Global: does ServOS do this and where is it? (Menu)', 'Global products follow to every venue the moment they change; a new venue receives every shared product. Where to find it: Menu, Sharing cards and strip.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Safe saves and Push to POS', 'Safe saves and Push to POS: does ServOS do this and where is it? (Menu)', 'Every edit saves only what changed and a conflict shows red; Push to POS sends the saved menu, floor plan, settings and profiles to every till, phone and kiosk. Where to find it: Back Office top bar, Push to POS.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Import menu (AI)', 'Import menu (AI): does ServOS do this and where is it? (Menu)', 'Drop a PDF, Word, Excel or photo menu and Claude reads categories and items for review and publish. Where to find it: Menu, Import menu.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Print menu', 'Print menu: does ServOS do this and where is it? (Menu)', 'Design a printable PDF menu with columns, paper, font, logo, allergens, prices and disclaimers. Where to find it: Back Office, Channels, Print menu.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Quick screen', 'Quick screen: does ServOS do this and where is it? (Menu)', 'Manual pins, automatic best sellers for the daypart, or hybrid; dayparts run on the venue clock. Where to find it: Till, Quick picks tab; set up in Menu, Quick screen.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Multi site menu', 'Multi site menu: does ServOS do this and where is it? (Menu)', 'One group menu for every site in the company: products, categories, option groups and sub items, which sites sell each one and the price at each. A grey price follows the group, a white one is that site''s own. Where to find it: Back Office, Menu, Multi site menu.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Per site price and on or off', 'Per site price and on or off: does ServOS do this and where is it? (Menu)', 'Switch a product on or off at any site, type prices like a spreadsheet or paste a column, and add a product to one, some or all sites. Prices and VAT by order type (Eat in, Takeaway, Collection, Drive thru) for the group and each site. Where to find it: Multi site menu, Products.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Change prices', 'Change prices: does ServOS do this and where is it? (Menu)', 'Pick products, categories or the whole menu; up or down by money or percent, or set a price; round to the penny, 5p or endings like .x9. A preview shows every price before and after at every site, with GP. Where to find it: Multi site menu, Change prices.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Scheduled change sets', 'Scheduled change sets: does ServOS do this and where is it? (Menu)', 'Every change goes into a named draft. Publish now, or schedule it (the Christmas menu on the tills by 1 Dec 06:00) on each site''s own clock. Counter tills take it between sales, never mid sale. The Timeline shows every set with a countdown. Where to find it: Multi site menu, Review and publish, Timeline.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Review and publish', 'Review and publish: does ServOS do this and where is it? (Menu)', 'See exactly what changes at each site first. Red problems stop it (no VAT rate, no category, a category that prints nowhere); risky changes need a tick (a price moving over 20%, a zero price, publishing while a site trades). Editors get an email an hour before a set if a site would fail. Where to find it: Multi site menu, Review and publish.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'History and undo', 'History and undo: does ServOS do this and where is it? (Menu)', 'Every publish is kept as a version with each site''s result. Retry a site that failed; Undo makes a new draft that puts it back. Where to find it: Multi site menu, History.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Option groups for every site', 'Option groups for every site: does ServOS do this and where is it? (Menu)', 'Build Milk, Syrups or Choose 3 donuts once, with a group price, on or off and a price per site. A site can keep its own rule. Where to find it: Multi site menu, Option groups.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Set up and import', 'Set up and import: does ServOS do this and where is it? (Menu)', 'Reads each site''s menu, matches the same products and lets you settle the rest (Same product, Keep separate, Leave out), proving publish would change nothing first. Bring a site''s own products in later. Export prices to Excel and import them back. Where to find it: Multi site menu, Setting up, Sites, Prices in Excel.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Sites and Price spread', 'Sites and Price spread: does ServOS do this and where is it? (Menu)', 'A card per site (In sync, Scheduled, Failed with Retry, Changed at the venue); Add a site gives a new site the whole menu; Price spread shows sites drifting apart; a line names products with a recipe at one site and none at another. Where to find it: Multi site menu, Sites, Price spread.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Head office lock', 'Head office lock: does ServOS do this and where is it? (Menu)', 'In Menu Manager, what head office manages (name, prices, category, VAT, allergens, options) shows read only with a lock. Button colour, 86, print centre and recipes stay the site''s. Where to find it: Menu Manager.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'One price for a whole menu', 'One price for a whole menu: does ServOS do this and where is it? (Menu)', 'Open a menu''s settings, press Set every item on this menu to one price, see how many items change, confirm. It sets the menu price (sizes too), never the base price. Where to find it: Menu Manager, the pencil on a menu.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Same rules on every channel', 'Same rules on every channel: does ServOS do this and where is it? (Menu)', 'Kiosk, online, QR, catering, bar tabs, the handheld and delivery apps use the till''s own rules for price, VAT, discounts, loyalty and charges, proved by a test on every release. An item with no price is never sold at 0.00. Where to find it: automatic.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Timed menus keep the line price', 'Timed menus keep the line price: does ServOS do this and where is it? (Menu)', 'A line keeps the price it was added at when a menu starts or ends, on every channel. Online and QR follow a chosen menu''s own times. Where to find it: automatic.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Same product order everywhere', 'Same product order everywhere: does ServOS do this and where is it? (Menu)', 'Products show in the menu builder''s order on the till, bar, both kiosks, online, QR, catering, menu boards and the print menu, then by the order they were made. Where to find it: Menu, drag to reorder.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Sub items in Import menu', 'Sub items in Import menu: does ServOS do this and where is it? (Menu)', 'The AI marks add ons and choices (extra cheese, oat milk) as Sub items and every row has a Product or Sub item switch. Where to find it: Menu, Import menu.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Category picker in Modifier groups', 'Category picker in Modifier groups: does ServOS do this and where is it? (Menu)', 'On these products lists every category, sub categories as Parent > Sub. Where to find it: Menu, Modifier groups.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Head office lock shown at a site', 'Head office lock shown at a site: does ServOS do this and where is it? (Menu)', 'A product whose option groups head office sets shows a lock and cannot be ticked, and a press says how many were left unchanged. Where to find it: Modifier groups at a site.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Groups make a product modifiable', 'Groups make a product modifiable: does ServOS do this and where is it? (Menu)', 'A product given option groups by head office publishes as Modifiable, so the till opens its options. Where to find it: Multi site menu, Publish.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Bring a site''s own option groups in', 'Bring a site''s own option groups in: does ServOS do this and where is it? (Menu)', 'Groups built by hand at a venue are listed; Link or Bring in as a new group, writing nothing at the site. Where to find it: Multi site menu, Sites.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Sub items come with their groups', 'Sub items come with their groups: does ServOS do this and where is it? (Menu)', 'A brought in group brings its sub items (Gouda, Mozzarella) as group menu products, reusable in other groups and at other sites, with a repair for groups brought in earlier. Where to find it: Multi site menu, Sites.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Sync from sites', 'Sync from sites: does ServOS do this and where is it? (Menu)', 'One list of everything each site sells that the group menu does not (products, option groups, sub items), with Bring in and Bring in all. Where to find it: Multi site menu, Sites.', 'Set up: venue, menu, devices, staff / Menu', false, false),
('doc', 'servos-features-2026-11-15', 'Terminals (devices)', 'Terminals (devices): does ServOS do this and where is it? (Devices)', 'Register each device by type (POS, Kitchen Display, Kiosk, Handheld, Time Clock) with its production centre, profile and receipt printer; shows last seen. Where to find it: Back Office, Hardware, Terminals.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Pairing codes', 'Pairing codes: does ServOS do this and where is it? (Devices)', 'A 12 symbol single use code valid for a year, typed on the device; works for tills, kiosks, kitchen screens, TVs, time clocks and tablets with no lock out and retries on a network blip. Where to find it: Hardware, Terminals, Pairing code; Kiosks, Pair this kiosk.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Device setup choice', 'Device setup choice: does ServOS do this and where is it? (Devices)', 'A fresh device asks what it is for: till, kitchen display, kiosk, menu board or order screen. Where to find it: Device first run screen.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Device profiles', 'Device profiles: does ServOS do this and where is it? (Devices)', 'One profile per kind of till: name, colour, start screen, menu, order types, Starts on, flag number, table service, floor section, service charge, hidden features, auto print, sign out, notifications, training mode, payment mode. Where to find it: Back Office, Device profiles; Apply to this terminal.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Network and Sync', 'Network and Sync: does ServOS do this and where is it? (Devices)', 'Devices on the network with heartbeat, version, out of date flag and master status; Force sync this device. Where to find it: Back Office, Hardware, Network & sync.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Native apps', 'Native apps: does ServOS do this and where is it? (Devices)', 'KDS, Kiosk, Time Clock, Waitlist, Bookings, Manager, Owner, Staff and menu board apps on iPad and Android, full screen and self updating. Where to find it: App Store, TestFlight and Android APK links.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Master till rule', 'Master till rule: does ServOS do this and where is it? (Devices)', 'QR, online, kiosk and delivery app orders are sent to the kitchen only by the venue''s real master till, with its menu loaded (it waits up to 20 seconds for the menu and looks again when it wakes or the connection returns). The master setting belongs to the till it was given to and is cleared when that till is unpaired. The Devices page says whether the master is on, when it was last seen, or that none or more than one is set. Other tills show Master POS offline after about 30 seconds if it goes. Where to find it: Back Office, Devices.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Messages from ServOS', 'Messages from ServOS: does ServOS do this and where is it? (Devices)', 'When ServOS needs a venue to do something (for example after an update) a message pops up on the venue''s tills and in Back Office and stays until Got it. Where to find it: automatic.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Demo pairing codes pair again', 'Demo pairing codes pair again: does ServOS do this and where is it? (Devices)', 'At a venue flagged as a demo venue only, a pairing code is not used up, so App Store reviewers can reinstall and pair again. Where to find it: Devices, demo venues.', 'Set up: venue, menu, devices, staff / Devices', false, false),
('doc', 'servos-features-2026-11-15', 'Staff and access', 'Staff and access: does ServOS do this and where is it? (Staff access)', 'Add staff with a POS role (Manager, Server, Bartender, Cashier, Kitchen, Host) and a 4 digit PIN; grant Back Office access. Where to find it: Back Office, Team.', 'Set up: venue, menu, devices, staff / Staff access', false, false),
('doc', 'servos-features-2026-11-15', 'Permissions', 'Permissions: does ServOS do this and where is it? (Staff access)', 'Per person: discounts, voids, refunds, price override, open drawer, cash up, end of day, reports, approvals, operations checks, manage staff. Where to find it: Team, Permissions.', 'Set up: venue, menu, devices, staff / Staff access', false, false),
('doc', 'servos-features-2026-11-15', 'What each login can open', 'What each login can open: does ServOS do this and where is it? (Staff access)', 'When you give someone a Back Office login, or edit one, tick the parts of Back Office they can use; the rest is hidden and locked. Only a company owner (or ServOS) can change it, nobody can change their own, owners always see everything. If access cannot be read at sign in the screen says so and offers Try again. Where to find it: Back Office, Team.', 'Set up: venue, menu, devices, staff / Staff access', false, false),
('doc', 'servos-features-2026-11-15', 'Staff PIN sign in', 'Staff PIN sign in: does ServOS do this and where is it? (Signing in)', 'Every sale, void and discount carries a name. Where to find it: Till sign in screen.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Staff card tap sign in', 'Staff card tap sign in: does ServOS do this and where is it? (Signing in)', 'Tap a staff card on built in NFC or a USB reader; assign the card by tapping it in Team; a card enrolled moments ago works at once. Where to find it: Till sign in; Team, Sign in method.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Fingerprint sign in', 'Fingerprint sign in: does ServOS do this and where is it? (Signing in)', 'Fingerprint login on Sunmi D3 Pro tills with PIN as fallback. Where to find it: Till sign in, Sunmi D3 Pro only.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Manager override for a lost card', 'Manager override for a lost card: does ServOS do this and where is it? (Signing in)', 'A manager allows a one off PIN sign in. Where to find it: Till sign in, Manager override.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Sign out behaviour', 'Sign out behaviour: does ServOS do this and where is it? (Signing in)', 'Automatic sign out after inactivity, after payment or after sending; never mid payment. Where to find it: Device profiles, Sign out behaviour.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Held order per operator', 'Held order per operator: does ServOS do this and where is it? (Signing in)', 'An unsent counter order parks under its owner when someone else signs in and comes back when they return. Where to find it: Till, automatic.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Start your shift prompt', 'Start your shift prompt: does ServOS do this and where is it? (Signing in)', 'The first sign in each day offers one tap to clock in. Where to find it: Till sign in; switch in Workforce settings.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Training mode', 'Training mode: does ServOS do this and where is it? (Signing in)', 'The till behaves normally but commits nothing: no sales, tickets, charges, receipts, stock or loyalty; a loud banner shows. Where to find it: Device profiles, Training mode.', 'Taking orders: till, bar, tables, phone till / Signing in', false, false),
('doc', 'servos-features-2026-11-15', 'Menu grid', 'Menu grid: does ServOS do this and where is it? (Building the order)', 'Category rail with counts, sub categories, colour tinted tiles, a true from price and optional photos. Where to find it: Till, POS screen.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Search', 'Search: does ServOS do this and where is it? (Building the order)', 'Type to find items across the till''s menu. Where to find it: Till, search box.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Options and modifiers', 'Options and modifiers: does ServOS do this and where is it? (Building the order)', 'Sizes and variants as big buttons, then required and optional groups with quantities and prices; items with no options add in one tap. Where to find it: Till, Set options panel.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Custom item', 'Custom item: does ServOS do this and where is it? (Building the order)', 'A one off item with its own name, price and note. Where to find it: Till, Custom item.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Item notes and kitchen note', 'Item notes and kitchen note: does ServOS do this and where is it? (Building the order)', 'A note per line and one note for the whole order, on tickets and screens. Where to find it: Till, line actions and order note.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Quantity, seats and courses', 'Quantity, seats and courses: does ServOS do this and where is it? (Building the order)', 'Change quantity, move a line to a seat, set Immediate or Course 1 to 3 and fire a held course; course controls can be hidden per till. Where to find it: Till, line actions and Fire; Device profiles, Hidden features.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Order panel follows adds', 'Order panel follows adds: does ServOS do this and where is it? (Building the order)', 'A new line scrolls into view and flashes. Where to find it: Till, order panel.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Order review', 'Order review: does ServOS do this and where is it? (Building the order)', 'A compact or detailed read through before sending. Where to find it: Till, Review.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Sold out (86)', 'Sold out (86): does ServOS do this and where is it? (Building the order)', 'Mark an item or one size sold out from the till; every till, kiosk, online, QR, phone, menu board and channel menu follows within seconds; Un 86 brings it back. Where to find it: Till, long press a tile; Menu Manager.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Daily counts', 'Daily counts: does ServOS do this and where is it? (Building the order)', 'Set how many you have today; the tile counts down, shows Running low, 86s itself at zero and the kiosk shows Only N left. Where to find it: Till, item info, Daily count; Back Office, Inventory, Daily counts.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', '86 on options', '86 on options: does ServOS do this and where is it? (Building the order)', 'An item is blocked when every option in a required group is sold out, on till, kiosk, online and phone. Where to find it: Automatic.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Item info sheet', 'Item info sheet: does ServOS do this and where is it? (Building the order)', 'Long press for allergens, sizes, pricing, options, recipe and method. Where to find it: Till, long press any tile.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Allergen filter', 'Allergen filter: does ServOS do this and where is it? (Building the order)', 'Tick a guest''s allergens and the grid shows safe items only; an attached customer''s saved allergens apply and new ones save to their profile; same on the phone till. Where to find it: Till and phone till, Allergen filter.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Allergen check before payment', 'Allergen check before payment: does ServOS do this and where is it? (Building the order)', 'Pay shows an Allergen check required screen when a line carries an active allergen. Where to find it: Till, on Pay.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Pre order lines from bookings', 'Pre order lines from bookings: does ServOS do this and where is it? (Building the order)', 'Pre ordered items seat with the table and show a badge until a missing choice is set. Where to find it: Till, table order panel.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Challenge ID (alcohol)', 'Challenge ID (alcohol): does ServOS do this and where is it? (Building the order)', 'Every so many alcohol sales the till asks staff to record an ID check or a refusal. Where to find it: Till, ID check; Back Office, Challenge ID.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Option only categories hidden', 'Option only categories hidden: does ServOS do this and where is it? (Building the order)', 'A category holding only sub items not sold alone is left off the till, bar screen and phone till. Where to find it: Till category strip.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Category tap closes options', 'Category tap closes options: does ServOS do this and where is it? (Building the order)', 'Tapping a category or sub category closes an open options or sizes screen and shows that category. Where to find it: Till.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Allergen filter shows open', 'Allergen filter shows open: does ServOS do this and where is it? (Building the order)', 'The Allergen filter button lights up while its list is open, red once a filter is on. Where to find it: Till left bar.', 'Taking orders: till, bar, tables, phone till / Building the order', false, false),
('doc', 'servos-features-2026-11-15', 'Order types', 'Order types: does ServOS do this and where is it? (Order types and customer details)', 'Dine in, Takeaway, Collection, Delivery and Drive thru, repriced as the type changes; only the ticked types show. Where to find it: Till order type bar; Device profiles, Enabled order types.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Order type the till starts on', 'Order type the till starts on: does ServOS do this and where is it? (Order types and customer details)', 'Each profile names the type the till opens on, applied on boot and after every order. Where to find it: Device profiles, Starts on.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Flag number on dine in orders', 'Flag number on dine in orders: does ServOS do this and where is it? (Order types and customer details)', 'For numbered table signs, the till asks for the flag before Send or Pay and tickets, screens and receipts read Table and the number. Where to find it: Device profiles, Ask for a flag number; kiosk Flag number mode.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Customer details on the till', 'Customer details on the till: does ServOS do this and where is it? (Order types and customer details)', 'One setting for what the till asks when a customer goes on an order: Full details, Name only or Not needed. Where to find it: Location settings, Customer details on the till.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Collection time and kitchen start', 'Collection time and kitchen start: does ServOS do this and where is it? (Order types and customer details)', 'Collection takes ASAP or a slot quoted from the real wait; a later order is held and fired the set minutes before, separate from the wait the customer is told. Where to find it: Till customer form; Location settings, Fire to kitchen N minutes before collection.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Delivery address and courier quote', 'Delivery address and courier quote: does ServOS do this and where is it? (Order types and customer details)', 'Delivery takes the address, fetches a Stuart quote onto the bill and blocks out of range or below minimum orders. Where to find it: Till, Delivery; Back Office, Delivery.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Drive thru', 'Drive thru: does ServOS do this and where is it? (Order types and customer details)', 'Its own order type and pink Orders tab, name or car only. Where to find it: Till and Orders; Device profiles.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Send without a table', 'Send without a table: does ServOS do this and where is it? (Order types and customer details)', 'Name the order, add it to a table (seat, merge or new check) or send as an unnamed counter order. Where to find it: Till, Send.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Add customer to the order', 'Add customer to the order: does ServOS do this and where is it? (Order types and customer details)', 'Live search by name, phone or email, remove with the X, chip shows stamps. Where to find it: Till, Add customer chip; phone till.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Link to existing member', 'Link to existing member: does ServOS do this and where is it? (Order types and customer details)', 'Link a new number to an imported member with no phone; name, allergens and stamps follow. Where to find it: Till, customer chip, Link to existing member.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Order details pop up', 'Order details pop up: does ServOS do this and where is it? (Order types and customer details)', 'One screen pops up before a walk in order is sent or paid with up to four parts: order type, New customer? Yes or No, flag number and how many guests. Each part has its own switch next to the flag number switch and only the parts switched on show; nothing is asked twice; floor tables never see it. Guests go on the kitchen card, the production ticket and the closed check as covers; Yes to New customer puts a NEW CUSTOMER badge on the kitchen card and in big print on the ticket. Where to find it: Devices, device profile, Starts on.', 'Taking orders: till, bar, tables, phone till / Order types and customer details', false, false),
('doc', 'servos-features-2026-11-15', 'Floor plan', 'Floor plan: does ServOS do this and where is it? (Floor plan and tables)', 'Tables by section with live status, time seated, running totals, zoom and auto fit; a till can default to its own section. Where to find it: Floor plan screen; layout in Back Office, Floor plan builder.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Seat guests', 'Seat guests: does ServOS do this and where is it? (Floor plan and tables)', 'Seat with covers, server and an optional guest. Where to find it: Floor plan, tap a free table.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Reserved from bookings', 'Reserved from bookings: does ServOS do this and where is it? (Floor plan and tables)', 'A booked table shows time and guest ahead of arrival and seats the booking with packages and pre orders. Where to find it: Floor plan, table panel.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Table actions', 'Table actions: does ServOS do this and where is it? (Floor plan and tables)', 'Edit covers, move, combine or transfer; kitchen tickets follow. Where to find it: Floor plan and till, table actions.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Split a table into checks', 'Split a table into checks: does ServOS do this and where is it? (Floor plan and tables)', 'A separate check on the same table (T1.2) with a check selector. Where to find it: Till, Send and table panel.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Attach a guest to a table', 'Attach a guest to a table: does ServOS do this and where is it? (Floor plan and tables)', 'Allergens and loyalty follow into the till. Where to find it: Floor plan, Add guest.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Close table and take payment', 'Close table and take payment: does ServOS do this and where is it? (Floor plan and tables)', 'Pay from the floor, force close a stuck table, print the bill. Where to find it: Floor plan table panel.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Tables and open orders stay in step', 'Tables and open orders stay in step: does ServOS do this and where is it? (Floor plan and tables)', 'Tables survive refresh and wake; open orders and bar tabs are reconciled across tills every 15 seconds. Where to find it: Automatic on every till.', 'Taking orders: till, bar, tables, phone till / Floor plan and tables', false, false),
('doc', 'servos-features-2026-11-15', 'Open a bar tab', 'Open a bar tab: does ServOS do this and where is it? (Bar tabs)', 'Name, bar seat or linked table, note, rounds with notes; same item in a round merges. Where to find it: Bar screen; can be hidden per till.', 'Taking orders: till, bar, tables, phone till / Bar tabs', false, false),
('doc', 'servos-features-2026-11-15', 'Card pre authorisation on a tab', 'Card pre authorisation on a tab: does ServOS do this and where is it? (Bar tabs)', 'Hold an amount when the tab opens, step it up as it grows, capture or release at close; the processor is recorded so refunds go back right. Where to find it: Bar screen, Open tab.', 'Taking orders: till, bar, tables, phone till / Bar tabs', false, false),
('doc', 'servos-features-2026-11-15', 'Void a round', 'Void a round: does ServOS do this and where is it? (Bar tabs)', 'With manager PIN and reason. Where to find it: Bar screen, Void round.', 'Taking orders: till, bar, tables, phone till / Bar tabs', false, false),
('doc', 'servos-features-2026-11-15', 'Tab notes', 'Tab notes: does ServOS do this and where is it? (Bar tabs)', 'Birthday or VIP notes on the tab. Where to find it: Bar screen, Tab note.', 'Taking orders: till, bar, tables, phone till / Bar tabs', false, false),
('doc', 'servos-features-2026-11-15', 'Tabs priced like the counter', 'Tabs priced like the counter: does ServOS do this and where is it? (Bar tabs)', 'A round is priced and taxed as the counter rings eat in, automatic deals run, and staff can add a manual discount line. Picking 3 of a drink adds 3. Where to find it: Bar screen.', 'Taking orders: till, bar, tables, phone till / Bar tabs', false, false),
('doc', 'servos-features-2026-11-15', 'Home, Orders, Tables, Me', 'Home, Orders, Tables, Me: does ServOS do this and where is it? (Phone till (MPOS))', 'My open tables, live queue, recently paid, a new order button and a Me tab with shift and reader status. Where to find it: Phone till app; Device profiles, Payment mode, MPOS.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'New order flow', 'New order flow: does ServOS do this and where is it? (Phone till (MPOS))', 'Order type, customer details by the venue rule, covers, search first menu, size picker, options with sold out, cart with To send and Already sent. Where to find it: Phone till.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'Line and order actions', 'Line and order actions: does ServOS do this and where is it? (Phone till (MPOS))', 'Note, course, discount, void or remove a line; order note, fire a course, transfer table. Where to find it: Phone till, Order actions.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'Send and pay', 'Send and pay: does ServOS do this and where is it? (Phone till (MPOS))', 'Send to kitchen, pay by Tap to Pay or an assigned reader or send to the counter, then print, email or skip the receipt; failures block the screen until handled. Where to find it: Phone till, Take payment.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'Closed orders and refunds', 'Closed orders and refunds: does ServOS do this and where is it? (Phone till (MPOS))', 'Browse by day, email a receipt, full or item refund with reason. Where to find it: Phone till, Closed orders.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'Manager PIN on the phone', 'Manager PIN on the phone: does ServOS do this and where is it? (Phone till (MPOS))', 'Approves a void, discount or refund for 90 seconds. Where to find it: Phone till, Manager required.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'Voice order', 'Voice order: does ServOS do this and where is it? (Phone till (MPOS))', 'Speak the order and the phone turns it into lines to confirm. Where to find it: Phone till, Voice order.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'No simulated card in production', 'No simulated card in production: does ServOS do this and where is it? (Phone till (MPOS))', 'A handset with no reader stops on an error instead of offering Simulate approved. Where to find it: Phone till, card payment.', 'Taking orders: till, bar, tables, phone till / Phone till (MPOS)', false, false),
('doc', 'servos-features-2026-11-15', 'Till shell', 'Till shell: does ServOS do this and where is it? (Till shell)', 'Left rail with POS, Floor, Bar and Orders, links to kiosk, online, QR and delivery, light and dark theme, activity feed bell, Terminal status, Support chat, What''s new, offline banner. Where to find it: Till.', 'Taking orders: till, bar, tables, phone till / Till shell', false, false),
('doc', 'servos-features-2026-11-15', 'Card on the Adyen reader', 'Card on the Adyen reader: does ServOS do this and where is it? (Card on the reader)', 'Pressing Card sends the exact bill to the reader bound to this till; the reader takes the card and the till books the sale. Where to find it: Checkout, Card machine.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Card screen opens within 3 seconds', 'Card screen opens within 3 seconds: does ServOS do this and where is it? (Card on the reader)', 'The till shows Customer is paying within 3 seconds, hides Close and Cash and watches the job from the first second. Where to find it: Checkout card screen.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Cancel a live payment', 'Cancel a live payment: does ServOS do this and where is it? (Card on the reader)', 'Staff cancel while the reader waits; the till asks the reader to stop then checks what really happened. Where to find it: Checkout card screen, Cancel.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Plain decline reasons', 'Plain decline reasons: does ServOS do this and where is it? (Card on the reader)', 'Wrong PIN, not enough balance, card refused, contactless limit, flat battery in plain words. Where to find it: Checkout card screen.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Order number fixed at send', 'Order number fixed at send: does ServOS do this and where is it? (Card on the reader)', 'Receipt, ticket, History and reports share one number whichever device records the sale. Where to find it: Checkout, automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'One device books the sale', 'One device books the sale: does ServOS do this and where is it? (Card on the reader)', 'The sending till books first; kitchen screens and Back Office tabs wait 30 to 90 seconds as a fallback so a paid job is never stranded. Where to find it: Automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Card approved after checkout closed', 'Card approved after checkout closed: does ServOS do this and where is it? (Card on the reader)', 'The till books it, clears the order and shows a sticky do not charge again banner. Where to find it: Till order screen.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Double charge protection', 'Double charge protection: does ServOS do this and where is it? (Card on the reader)', 'The server refuses a second charge of the same order within 10 minutes and offers Open the sale, Clear this order or Different customer; a running payment offers Watch that payment; an amber note warns when the same basket paid in the last 5 minutes. Where to find it: Checkout card screen.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Same card, same amount alert', 'Same card, same amount alert: does ServOS do this and where is it? (Card on the reader)', 'An approval on the same card for the same amount within 15 minutes raises an urgent note. Where to find it: Activity feed bell.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Split bill', 'Split bill: does ServOS do this and where is it? (Card on the reader)', 'Evenly, by seat, by item or custom amounts; each portion pays by card, cash or gift card with its own tip and the table books as one check. Where to find it: Checkout, Split check.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Pay at table on the reader', 'Pay at table on the reader: does ServOS do this and where is it? (Card on the reader)', 'Staff or guests pay part or all of a table on the reader; the table closes on every till the moment it is paid; button on or off per reader. Where to find it: Reader, Pay at table; Back Office, Card readers.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Already paid guards', 'Already paid guards: does ServOS do this and where is it? (Card on the reader)', 'A paid bill cannot be charged again; an online, QR or catering order whose payment is still being checked offers Check payment or a manager''s Confirm payment. Where to find it: Checkout and Orders.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Updates never interrupt a payment', 'Updates never interrupt a payment: does ServOS do this and where is it? (Card on the reader)', 'A release waits while any checkout, card screen, tab capture or phone tender is open. Where to find it: Automatic on every device.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Card reader status for the cashier', 'Card reader status for the cashier: does ServOS do this and where is it? (Card on the reader)', 'Which reader this till sends to and when it was last seen. Where to find it: Till, status drawer.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Card machine frees itself', 'Card machine frees itself: does ServOS do this and where is it? (Card on the reader)', 'When a card machine never receives a payment it frees itself in under 3 minutes, and at once when the machine says it never got it. It used to stay busy for 5 minutes or more and refuse every new payment. Staff hear a sound and the message says Card machine is free and the amount that was not charged. A payment the machine says is still in progress is never cancelled by the system. Where to find it: automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Prepaid tables on the reader', 'Prepaid tables on the reader: does ServOS do this and where is it? (Card on the reader)', 'Pay at table and PAX Table Pay charge only what is left after a booking''s prepay or deposit, and close the table when it is covered. Where to find it: Reader, Pay at table.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card on the reader', false, false),
('doc', 'servos-features-2026-11-15', 'Stuck payment checked and cleared', 'Stuck payment checked and cleared: does ServOS do this and where is it? (Self healing)', 'When a reader drops mid payment the till asks Adyen''s own record and finishes or clears the sale; never guesses. Where to find it: Checkout card screen, automatic plus one tap.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Every minute sweep', 'Every minute sweep: does ServOS do this and where is it? (Self healing)', 'A server sweep books approved payments that never settled. Where to find it: Server, automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Tip heal', 'Tip heal: does ServOS do this and where is it? (Self healing)', 'A reader total above the bill that is a tip the reader asked for is corrected onto the sale within seconds. Where to find it: Server, automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Amount mismatch alert', 'Amount mismatch alert: does ServOS do this and where is it? (Self healing)', 'Anything not fixable raises one alert with both amounts and lands in Unresolved payments. Where to find it: Activity feed; Back Office, Card readers.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Unresolved payments queue', 'Unresolved payments queue: does ServOS do this and where is it? (Self healing)', 'A manager marks each one Taken, Not taken or Declined or signs off a difference, stamped with their name. Where to find it: Back Office, Hardware, Card readers, bottom panel.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Release stuck payment', 'Release stuck payment: does ServOS do this and where is it? (Self healing)', 'Frees a reader that says a payment is in progress when nothing is. Where to find it: Card readers, each reader.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Reader never asked in its first 2 minutes', 'Reader never asked in its first 2 minutes: does ServOS do this and where is it? (Self healing)', 'A slow reader is never cancelled by the till. Where to find it: Automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Self healing', false, false),
('doc', 'servos-features-2026-11-15', 'Cash', 'Cash: does ServOS do this and where is it? (Cash)', 'Quick cash and Exact, change or short by, change due full screen until tapped, drawer pops on Sunmi, Epson and Star; shows only when a drawer is bound. Where to find it: Checkout, Cash.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Cash', false, false),
('doc', 'servos-features-2026-11-15', 'Cash in and POS lock', 'Cash in and POS lock: does ServOS do this and where is it? (Cash)', 'A till with a drawer locks until a manager counts the float in by denomination. Where to find it: Till, POS locked screen; Back Office, Cash drawers.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Cash', false, false),
('doc', 'servos-features-2026-11-15', 'Till functions', 'Till functions: does ServOS do this and where is it? (Cash)', 'No sale, Pay in, Pay out or expense, Cash drop with amount and reason, recent drawer activity; every movement hits the ledger. Where to find it: Till, Till functions.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Cash', false, false),
('doc', 'servos-features-2026-11-15', 'Cash up', 'Cash up: does ServOS do this and where is it? (Cash)', 'Count by denomination or quick total, expected and variance, pop the drawer, print the Z report, sign out. Where to find it: Till functions, Cash up.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Cash', false, false),
('doc', 'servos-features-2026-11-15', 'Cash drawers', 'Cash drawers: does ServOS do this and where is it? (Cash)', 'Define each drawer, bind it to its printer and till, see Idle, Open or Counting. Where to find it: Back Office, Hardware, Cash drawers.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Cash', false, false),
('doc', 'servos-features-2026-11-15', 'US and euro cash drawer', 'US and euro cash drawer: does ServOS do this and where is it? (Cash)', 'A US venue counts $100 to $1 bills then quarters, dimes, nickels and pennies; euro venues count euro notes and cents; UK venues see the list they had. Counts add up in pennies so three 10p coins always make 30p. Where to find it: Cash in, Cash up, Cash drawers, End of day.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Cash', false, false),
('doc', 'servos-features-2026-11-15', 'Gift cards as a tender', 'Gift cards as a tender: does ServOS do this and where is it? (Other tenders)', 'One box for a gift card or promo code on till, kiosk, online and QR; the balance is taken only when the sale completes and put back if the card job fails. Where to find it: Checkout, Gift card or promo code box.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Other tenders', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty rewards at checkout', 'Loyalty rewards at checkout: does ServOS do this and where is it? (Other tenders)', 'The member''s points and stamp cards show, staff or the customer pick a reward and it applies at payment; points earn after payment. Where to find it: Checkout, Loyalty rewards; kiosk and online.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Other tenders', false, false),
('doc', 'servos-features-2026-11-15', 'Redeem several rewards on one order', 'Redeem several rewards on one order: does ServOS do this and where is it? (Other tenders)', 'More than one stamp reward on different eligible items; the till shows 2 of 3 used; refunds give stamps back. Where to find it: Checkout, Redeem a reward.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Other tenders', false, false),
('doc', 'servos-features-2026-11-15', 'Promo codes at checkout', 'Promo codes at checkout: does ServOS do this and where is it? (Other tenders)', 'A marketing code checked live and redeemed once at payment; lowers the taxed amount in the US. Where to find it: Till, kiosk, online and catering checkout.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Other tenders', false, false),
('doc', 'servos-features-2026-11-15', 'Booking deposit credit', 'Booking deposit credit: does ServOS do this and where is it? (Other tenders)', 'A prepaid package or deposit comes off the bill as its own tender. Where to find it: Checkout, Booking deposit line.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Other tenders', false, false),
('doc', 'servos-features-2026-11-15', 'Every tender recorded', 'Every tender recorded: does ServOS do this and where is it? (Other tenders)', 'Each check records card, cash, gift card, booking credit, loyalty and promo credit so Xero and reports get the right split. Where to find it: Automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Other tenders', false, false),
('doc', 'servos-features-2026-11-15', 'Discounts', 'Discounts: does ServOS do this and where is it? (Discounts, service charge and tips)', 'The venue''s own presets or a custom amount or percent on the check or selected lines; a preset can require a manager PIN and the approver is recorded by name; each venue shows only its own presets (beta). Where to find it: Till, Discount; Back Office, Menu, Discounts.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Service charge', 'Service charge: does ServOS do this and where is it? (Discounts, service charge and tips)', 'Percent on dine in, all tables or from a minimum covers; staff can remove or restore it. Where to find it: Till totals; Device profiles, Service charge.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Tips on the card reader', 'Tips on the card reader: does ServOS do this and where is it? (Discounts, service charge and tips)', 'Tips on or off, up to 5 whole percentages, custom amount, ask on till payments; written to the Adyen store and every reader. Where to find it: Back Office, Card readers, Tips.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Reader tip rules on every order type', 'Reader tip rules on every order type: does ServOS do this and where is it? (Discounts, service charge and tips)', 'Takeaway, collection and drive thru follow the reader''s tip settings; only bar tabs skip the prompt. Where to find it: Automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Tips worked out the same everywhere', 'Tips worked out the same everywhere: does ServOS do this and where is it? (Discounts, service charge and tips)', 'Percentages apply to food and drink after discounts only, never to tax, service or delivery. Where to find it: Till, reader, kiosk, online.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Tip on printed receipt (United States)', 'Tip on printed receipt (United States): does ServOS do this and where is it? (Discounts, service charge and tips)', 'Pre authorise, print a tip line on the merchant copy, add the written tip from History; a forgotten tip captures at the original amount. Where to find it: Card readers, Tips; till History.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Tip capture retries', 'Tip capture retries: does ServOS do this and where is it? (Discounts, service charge and tips)', 'If the bank refuses overcapture the system asks for the new total and completes the tip. Where to find it: Server, automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Discount kinds', 'Discount kinds: does ServOS do this and where is it? (Discounts, service charge and tips)', 'Each discount is an Ordinary discount, Staff food and drink, Comp or Loyalty reward, so reports show staff food, comps and rewards on their own line. Prices do not change. Where to find it: Back Office, Menu, Discounts.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Discounts, service charge and tips', false, false),
('doc', 'servos-features-2026-11-15', 'Print and auto print receipt', 'Print and auto print receipt: does ServOS do this and where is it? (Receipts)', 'On demand or when payment completes, to this till''s printer; online and delivery receipts go to the venue default printer. Where to find it: Checkout, Print receipt; Device profiles, Auto print.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Receipts', false, false),
('doc', 'servos-features-2026-11-15', 'Email receipt', 'Email receipt: does ServOS do this and where is it? (Receipts)', 'A VAT or sales tax compliant receipt using the Digital Receipt template. Where to find it: Checkout and History, Send receipt.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Receipts', false, false),
('doc', 'servos-features-2026-11-15', 'Receipt content', 'Receipt content: does ServOS do this and where is it? (Receipts)', 'Branding, address, ref and table or flag, lines, discounts, service, tax by rate, loyalty lines, UK card scheme block, footer QR. Where to find it: Back Office, Receipt branding.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Receipts', false, false),
('doc', 'servos-features-2026-11-15', 'Discount lines on receipts and History', 'Discount lines on receipts and History: does ServOS do this and where is it? (Receipts)', 'Each discount by name and amount on the printed receipt and the History screen, the figure the saved bill carries. Where to find it: Till receipts; History.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Receipts', false, false),
('doc', 'servos-features-2026-11-15', 'Void a line or the whole order', 'Void a line or the whole order: does ServOS do this and where is it? (Voids and refunds)', 'Any order type with manager PIN and reason; the kitchen sees a VOID banner and reports read the void; also from Orders Hub. Where to find it: Till, Void; Orders, Void.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'Remove unsent lines', 'Remove unsent lines: does ServOS do this and where is it? (Voids and refunds)', 'Lines not yet sent go without a void. Where to find it: Till, Remove and Clear all.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'History and refunds', 'History and refunds: does ServOS do this and where is it? (Voids and refunds)', 'Completed orders with full or item refund to the original card or cash, reasons, reprint, email, tip window status; tip, service and tax corrected on a full refund. Where to find it: Till, History; Back Office, Transactions.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'Refund shows the card it will go to', 'Refund shows the card it will go to: does ServOS do this and where is it? (Voids and refunds)', 'If the sale record cannot be reached it records nothing so the refund can be retried. Where to find it: History and Back Office refund screen.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'Cash payout refund', 'Cash payout refund: does ServOS do this and where is it? (Voids and refunds)', 'Hand the refund back from the drawer. Where to find it: History, Cash payout.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'Gift card and loyalty reversed on refund', 'Gift card and loyalty reversed on refund: does ServOS do this and where is it? (Voids and refunds)', 'Spend goes back on the card and points return. Where to find it: Automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'Fair part refunds', 'Fair part refunds: does ServOS do this and where is it? (Voids and refunds)', 'A part refund on a discounted bill gives back what was really taken for those items, with their own VAT. A gift card share goes back on the card, the stamps and points of those items come back, and a promo code is given back on a full refund. Where to find it: History.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Voids and refunds', false, false),
('doc', 'servos-features-2026-11-15', 'Add a reader by serial', 'Add a reader by serial: does ServOS do this and where is it? (Card reader set up)', 'Type the serial; it registers on the venue''s Adyen store and settings push at once. Where to find it: Back Office, Hardware, Card readers, Add a reader.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Readers list', 'Readers list: does ServOS do this and where is it? (Card reader set up)', 'Status, rename, refresh, remove, and readers on the store not yet added. Where to find it: Card readers.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Take payments from the till', 'Take payments from the till: does ServOS do this and where is it? (Card reader set up)', 'Bind each reader to a named till or Any till; a till can never borrow another till''s reader. Where to find it: Card readers, each reader.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Staff can type an amount on the reader', 'Staff can type an amount on the reader: does ServOS do this and where is it? (Card reader set up)', 'Allows a manual amount started on the reader. Where to find it: Card readers, each reader.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Admin PIN on the readers', 'Admin PIN on the readers: does ServOS do this and where is it? (Card reader set up)', 'Read or set the admin menu PIN. Where to find it: Card readers, Advanced.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Send reader settings to Adyen', 'Send reader settings to Adyen: does ServOS do this and where is it? (Card reader set up)', 'Re push store settings if a reader is out of step. Where to find it: Card readers, Advanced.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Environment and Adyen ids', 'Environment and Adyen ids: does ServOS do this and where is it? (Card reader set up)', 'Test or live with a red banner while live, read only. Where to find it: Card readers, Advanced, Environment.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Card terminal for a kiosk', 'Card terminal for a kiosk: does ServOS do this and where is it? (Card reader set up)', 'A kiosk sends payments to its paired reader like a till, and checks the reader is linked to the venue before it starts. Where to find it: Card readers, Assign to a till or kiosk; Kiosks, Card terminal.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'MPOS handheld on an Adyen terminal', 'MPOS handheld on an Adyen terminal: does ServOS do this and where is it? (Card reader set up)', 'The handheld is till and reader in one over its own local connection. Where to find it: MPOS app on an Adyen Android terminal.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Reader status in plain words', 'Reader status in plain words: does ServOS do this and where is it? (Card reader set up)', 'The till status page reads Connected to Adyen for an Adyen reader; it used to say Not connected in red while the reader was taking payments. Where to find it: till status page.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card reader set up', false, false),
('doc', 'servos-features-2026-11-15', 'Adyen card form', 'Adyen card form: does ServOS do this and where is it? (Online and kiosk card payments)', 'Card details encrypted in the browser for online, QR, catering, gift purchase and bookings; result lands by webhook. Where to find it: Every customer checkout.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Online and kiosk card payments', false, false),
('doc', 'servos-features-2026-11-15', 'Apple Pay and Google Pay', 'Apple Pay and Google Pay: does ServOS do this and where is it? (Online and kiosk card payments)', 'Wallet buttons beside the card form once the shop address is registered; retries every 6 hours. Where to find it: Online and booking checkout; Admin, step 4.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Online and kiosk card payments', false, false),
('doc', 'servos-features-2026-11-15', 'Kiosk payment that never reaches the reader', 'Kiosk payment that never reaches the reader: does ServOS do this and where is it? (Online and kiosk card payments)', 'Found in seconds; the customer is told the card was not charged only when certain. Where to find it: Kiosk card screen.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Online and kiosk card payments', false, false),
('doc', 'servos-features-2026-11-15', 'Staff alerts for kiosk card problems', 'Staff alerts for kiosk card problems: does ServOS do this and where is it? (Online and kiosk card payments)', 'Every till shows an alert with amount and reference until someone taps OK. Where to find it: Tills, automatic.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Online and kiosk card payments', false, false),
('doc', 'servos-features-2026-11-15', 'Card payments', 'Card payments: does ServOS do this and where is it? (Card payments in Back Office)', 'Balances, payment list with In person and Online filters, disputes, payouts, documents and settings. Where to find it: Back Office, Card payments.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card payments in Back Office', false, false),
('doc', 'servos-features-2026-11-15', 'Processing rates shown to the venue', 'Processing rates shown to the venue: does ServOS do this and where is it? (Card payments in Back Office)', 'The real rate card per payment type. Where to find it: Card payments, Settings.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card payments in Back Office', false, false),
('doc', 'servos-features-2026-11-15', 'Complete your payout setup', 'Complete your payout setup: does ServOS do this and where is it? (Card payments in Back Office)', 'Adyen''s hosted page for bank account and identity checks. Where to find it: Card payments, Payouts.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card payments in Back Office', false, false),
('doc', 'servos-features-2026-11-15', 'Venue fees and statements', 'Venue fees and statements: does ServOS do this and where is it? (Card payments in Back Office)', 'Monthly statements on the venue''s time using the fee stamped on each payment. Where to find it: Card payments, Payouts.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card payments in Back Office', false, false),
('doc', 'servos-features-2026-11-15', 'Release stuck payment that works', 'Release stuck payment that works: does ServOS do this and where is it? (Card payments in Back Office)', 'It asks the card machine first, frees the job when that is safe and says why when it is not. Where to find it: Back Office, Card readers.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card payments in Back Office', false, false),
('doc', 'servos-features-2026-11-15', 'Payouts in full', 'Payouts in full: does ServOS do this and where is it? (Card payments in Back Office)', 'The Payouts list shows every settlement and each one in full; it used to stop at a venue''s first 1,000 card payments. Where to find it: Back Office, Card payments, Payouts.', 'Taking payment: card readers, cash, gift, loyalty, tips, refunds / Card payments in Back Office', false, false),
('doc', 'servos-features-2026-11-15', 'Kitchen display screen', 'Kitchen display screen: does ServOS do this and where is it? (Kitchen display screens)', 'A paired tablet or TV showing every order for its centre as a ticket, with a 20 second self refresh. Where to find it: KDS app or ?mode=kds; paired under Hardware, Terminals.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Order type colours', 'Order type colours: does ServOS do this and where is it? (Kitchen display screens)', 'Dine in by name green, table teal, Takeaway orange, Collection purple, Delivery pink, Drive thru blue. Where to find it: Ticket card; Station settings.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Ticket details', 'Ticket details: does ServOS do this and where is it? (Kitchen display screens)', 'Name or table, order number, source, staff, covers, elapsed timer, course, notes, allergens in capitals, CHECK ID for kiosk alcohol, red VOID block. Where to find it: Ticket card.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Bump', 'Bump: does ServOS do this and where is it? (Kitchen display screens)', 'Marks the ticket done; the big button on every card. Where to find it: Kitchen screen.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Undo bump', 'Undo bump: does ServOS do this and where is it? (Kitchen display screens)', '5 seconds to bring a ticket straight back. Where to find it: Kitchen screen header.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Tick items', 'Tick items: does ServOS do this and where is it? (Kitchen display screens)', 'Tick each item as made; untick a mistake; unticking never bumps. Where to find it: Tick box on each line.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Bump when every item is ticked', 'Bump when every item is ticked: does ServOS do this and where is it? (Kitchen display screens)', 'Optional auto bump, off by default. Where to find it: Station settings, Bumping.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Hold and Resume', 'Hold and Resume: does ServOS do this and where is it? (Kitchen display screens)', 'Dim in place or move to the end; the timer keeps counting. Where to find it: Hold on the card.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Courses on the kitchen ticket', 'Courses on the kitchen ticket: does ServOS do this and where is it? (Kitchen display screens)', 'Items group by course with FIRING and HOLD headers; the till fires the next course. Where to find it: Till Fire course; kitchen screen and docket.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Note for the kitchen', 'Note for the kitchen: does ServOS do this and where is it? (Kitchen display screens)', 'A 200 character note shown in green on every screen holding that order, never on receipts. Where to find it: Kitchen screen pop out.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Mark ready when the kitchen bumps', 'Mark ready when the kitchen bumps: does ServOS do this and where is it? (Kitchen display screens)', 'The last bump marks the order Ready so the customer gets their text; optionally also Collected. Where to find it: Back Office, Channels, Order screens.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Order type filter', 'Order type filter: does ServOS do this and where is it? (Kitchen display screens)', 'Tap a count pill to show one type; a banner says what is hidden and resets after 3 minutes or a hidden arrival. Where to find it: Kitchen screen header.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Recall last and History', 'Recall last and History: does ServOS do this and where is it? (Kitchen display screens)', 'Bring back today''s bumped tickets. Where to find it: Kitchen screen buttons.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'To make rail', 'To make rail: does ServOS do this and where is it? (Kitchen display screens)', 'Item quantities added up across live tickets, split by modifiers. Where to find it: Kitchen screen right rail.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Station buttons', 'Station buttons: does ServOS do this and where is it? (Kitchen display screens)', 'All stations plus a button per station. Where to find it: Kitchen screen header.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Station settings per screen', 'Station settings per screen: does ServOS do this and where is it? (Kitchen display screens)', 'Behind a manager PIN: what to show, held to the end, timer thresholds, colour by type or time, density. Where to find it: Kitchen screen, settings cog.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Kitchen clear screen', 'Kitchen clear screen: does ServOS do this and where is it? (Kitchen display screens)', 'Kitchen clear, All orders bumped when the board is empty. Where to find it: Kitchen screen.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Can''t reach banner and self heal', 'Can''t reach banner and self heal: does ServOS do this and where is it? (Kitchen display screens)', 'Keeps what is on screen and refetches on wake, network return and reconnect. Where to find it: Kitchen screen.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'KDS test ticket and status', 'KDS test ticket and status: does ServOS do this and where is it? (Kitchen display screens)', 'Kitchen displays online or offline, printers, print queue with Retry and Dismiss, test ticket; failure words say what is actually wrong. Where to find it: Till, Terminal status drawer.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Slow link protection', 'Slow link protection: does ServOS do this and where is it? (Kitchen display screens)', 'A slow or dropped link never brings a bumped ticket back or loses a bump. Every change carries its own guard, so a late write cannot undo a newer tap and a saved bump is never painted back by a late echo. The red banner says plainly when ServOS cannot be reached and does not blame the WiFi when ServOS itself answered with an error. The till says when a kitchen screen has stopped showing orders. Where to find it: automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Kitchen screens never delete', 'Kitchen screens never delete: does ServOS do this and where is it? (Kitchen display screens)', 'A kitchen screen never deletes an order, a bar tab or a table, in every shape of kitchen screen (KDS app, Kitchen Display inside a till page, a till profile that opens on the kitchen screen). A till deletes an order only when it was paid, voided, rejected or collected there. A catering order moved to a later day stays. Where to find it: automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Live update guard', 'Live update guard: does ServOS do this and where is it? (Kitchen display screens)', 'A kitchen screen, the till''s activity bell and the operations overview ignore a live update that carries an error and no data. Where to find it: automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Covers and new customer on the card', 'Covers and new customer on the card: does ServOS do this and where is it? (Kitchen display screens)', 'The guest count from the till pop up shows on the kitchen card and the production ticket, with a white NEW CUSTOMER badge when the cashier answered Yes. Where to find it: Kitchen screen card, production ticket, Orders.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Kitchen display screens', false, false),
('doc', 'servos-features-2026-11-15', 'Production centres', 'Production centres: does ServOS do this and where is it? (Production printing and routing)', 'Kitchen, Bar, Expo, Cold section, each with a printer and or a kitchen screen; dockets and KDS tickets come from the same bucket. Where to find it: Back Office, Production printing.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Category routing', 'Category routing: does ServOS do this and where is it? (Production printing and routing)', 'Tick categories per centre; the nearest ticked category wins. Where to find it: Production printing, routing tree.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Sub categories and sizes routing', 'Sub categories and sizes routing: does ServOS do this and where is it? (Production printing and routing)', 'Every sub category and size has its own box. Where to find it: Production printing, routing tree.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Not here and item exclusions', 'Not here and item exclusions: does ServOS do this and where is it? (Production printing and routing)', 'Block a category, product or size at a centre. Where to find it: Production printing, routing tree.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Order type routing per centre', 'Order type routing per centre: does ServOS do this and where is it? (Production printing and routing)', 'A centre takes all or chosen order types, with a warning when a type reaches no centre. Where to find it: Production printing, Order types card.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Kitchen docket', 'Kitchen docket: does ServOS do this and where is it? (Production printing and routing)', 'Big number or table, type, staff, covers, items by course, modifiers in red, kitchen names, allergens, notes, delivery details, paid status. Where to find it: Centre''s printer.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'One ticket per item (sticker mode)', 'One ticket per item (sticker mode): does ServOS do this and where is it? (Production printing and routing)', 'A separate docket per item numbered ITEM 1 OF 3. Where to find it: Production printing, centre editor.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Void docket', 'Void docket: does ServOS do this and where is it? (Production printing and routing)', 'A **VOID** docket prints and a red block shows so the cook stops. Where to find it: Till and Orders Hub void.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Reprint and duplicate dockets', 'Reprint and duplicate dockets: does ServOS do this and where is it? (Production printing and routing)', 'Reprint chosen items with a REPRINT banner; Send to kitchen again prints and puts the ticket back on the KDS. Where to find it: Till, Reprint; Orders Hub.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Fire course and transfer dockets', 'Fire course and transfer dockets: does ServOS do this and where is it? (Production printing and routing)', 'FIRE COURSE markers and transfer notices when a table moves. Where to find it: Centre''s printer, automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Scheduled and catering release', 'Scheduled and catering release: does ServOS do this and where is it? (Production printing and routing)', 'Pre orders and catering fire at kitchen start time, with a server backstop if no till is on. Where to find it: Automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Production printing and routing', false, false),
('doc', 'servos-features-2026-11-15', 'Printer list', 'Printer list: does ServOS do this and where is it? (Printers)', 'Network printers with name, area, model, IP, paper width (58, 80, 112 mm), purpose and cash drawer. Where to find it: Back Office, Hardware, Printers.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Printers', false, false),
('doc', 'servos-features-2026-11-15', 'Printer models and command sets', 'Printer models and command sets: does ServOS do this and where is it? (Printers)', 'ESC/POS for Sunmi, Epson, Bixolon, Citizen, Xprinter; Star Line Mode and Star raster, each with the mode it must be in. Where to find it: Printers, Printer model.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Printers', false, false),
('doc', 'servos-features-2026-11-15', 'Direct printing from the device', 'Direct printing from the device: does ServOS do this and where is it? (Printers)', 'Sunmi tills and the iPad app print straight to the printer on venue WiFi. Where to find it: Till app, automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Printers', false, false),
('doc', 'servos-features-2026-11-15', 'Print queue with retries', 'Print queue with retries: does ServOS do this and where is it? (Printers)', 'Every print is a durable job retried for half an hour; one printer, one job at a time; a kitchen ticket is never stuck behind a receipt. Where to find it: Automatic; Status drawer, Print queue.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Printers', false, false),
('doc', 'servos-features-2026-11-15', 'Test page', 'Test page: does ServOS do this and where is it? (Printers)', 'Name, model, command set, IP, width, source and app version so a photo tells support which path printed. Where to find it: Printers, Test.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Printers', false, false),
('doc', 'servos-features-2026-11-15', 'Printer errors in plain words', 'Printer errors in plain words: does ServOS do this and where is it? (Printers)', 'Says what to check instead of Agent not responding. Where to find it: Status drawer; Printers.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Printers', false, false),
('doc', 'servos-features-2026-11-15', 'Orders Hub', 'Orders Hub: does ServOS do this and where is it? (Orders Hub)', 'Every open order: Tables, Bar tabs, QR tabs, Counter, Takeaway, Collection, Delivery, Drive thru, kiosk, online and channel orders, for Today, Tomorrow and Later, with My orders and search. Where to find it: Till, Orders.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Order status flow', 'Order status flow: does ServOS do this and where is it? (Orders Hub)', 'Received, In prep, Ready, Collected; an unpaid order shows Charge instead of Collected; held pre orders show in violet with their fire time; Ready sends the customer''s message. Where to find it: Orders screen.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Keep paid till orders in Orders Hub', 'Keep paid till orders in Orders Hub: does ServOS do this and where is it? (Orders Hub)', 'Paid till orders stay until Collected so they show on the order screen and count in the wait. Where to find it: Channels, Order screens, Paid till orders.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Collection queue', 'Collection queue: does ServOS do this and where is it? (Orders Hub)', 'Takeaway and collection by time with Start prep, Mark ready and Collected. Where to find it: Kitchen screen collection view.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Channel orders', 'Channel orders: does ServOS do this and where is it? (Orders Hub)', 'Deliveroo, Uber Eats and Just Eat orders need Accept, Reject or Delay by 10 to 30 minutes; status mirrors back; default prep time per venue. Where to find it: Orders screen; Back Office, HubRise.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Order notifications on the till', 'Order notifications on the till: does ServOS do this and where is it? (Orders Hub)', 'Chime and alert for new online, kiosk, QR and channel orders, per terminal. Where to find it: Device profiles, Order notifications.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Collection wait and busy time', 'Collection wait and busy time: does ServOS do this and where is it? (Orders Hub)', 'The flat wait quoted online, on kiosk, QR and phone orders, plus minutes added for every so many live kitchen orders with a cap. Where to find it: Back Office, Online ordering, Operational; Kiosk settings, Average wait.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Send to kitchen again says what happened', 'Send to kitchen again says what happened: does ServOS do this and where is it? (Orders Hub)', 'Sent to the kitchen again, or Not sent; the till shows no message for a channel order that routed normally. Where to find it: Orders.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'QR order buttons', 'QR order buttons: does ServOS do this and where is it? (Orders Hub)', 'A QR order paid on the phone says what its button does (Mark in prep, Mark ready, Mark collected), and a finished QR order shows no dead button. Where to find it: Orders.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Close and charge Adyen QR tabs', 'Close and charge Adyen QR tabs: does ServOS do this and where is it? (Orders Hub)', 'An open Adyen QR tab can be closed and charged from Orders Hub. Where to find it: Orders Hub.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Orders Hub', false, false),
('doc', 'servos-features-2026-11-15', 'Order screen', 'Order screen: does ServOS do this and where is it? (Order screens (TV))', 'A TV showing received, preparing, ready and collected; ready rows sort first and pulse; it never scrolls, it shrinks, adds a column or pages in step. Where to find it: Channels, Order screens; menu board app or ?mode=orderscreen.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Order screens (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Order screen sections', 'Order screen sections: does ServOS do this and where is it? (Order screens (TV))', 'Title, channels, order types, steps, name style and source per section. Where to find it: Order screens editor, Sections.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Order screens (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Order screen design and timing', 'Order screen design and timing: does ServOS do this and where is it? (Order screens (TV))', 'Portrait or landscape, header and logo, status words, keep collected N minutes, hide old orders, sound when ready, live preview. Where to find it: Order screens editor.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Order screens (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Pair a TV to an order screen', 'Pair a TV to an order screen: does ServOS do this and where is it? (Order screens (TV))', 'Type the TV''s code, pick the screen, reassign or remove; shows online status. Where to find it: Order screens, Paired TVs.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Order screens (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Order screen privacy', 'Order screen privacy: does ServOS do this and where is it? (Order screens (TV))', 'The TV reads only a masked feed and stores nothing. Where to find it: Automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Order screens (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Order screen TVs keep their pairing', 'Order screen TVs keep their pairing: does ServOS do this and where is it? (Order screens (TV))', 'The same protection as menu boards: no drop to the pairing code on a bad live update or a network blip. Where to find it: automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Order screens (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Order confirmed and order ready messages', 'Order confirmed and order ready messages: does ServOS do this and where is it? (Customer messages)', 'SMS and email with the short order number on placing and on Ready, for online, kiosk, QR and phone orders; delivery gets courier tracking. Where to find it: Automatic; Back Office, Messages, Orders.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer messages', false, false),
('doc', 'servos-features-2026-11-15', 'Order tracker', 'Order tracker: does ServOS do this and where is it? (Customer messages)', 'The customer''s page follows the order through Received, Preparing, Ready and Collected with the real quoted time. Where to find it: Online ordering confirmation page.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer messages', false, false),
('doc', 'servos-features-2026-11-15', 'Menu board screens', 'Menu board screens: does ServOS do this and where is it? (Menu boards (TV))', 'Pick categories, drag to reorder, headings, auto fit to one screen, live price and sold out updates, offline cache. Where to find it: Channels, Menu boards; menu board app or ?mode=menuboard.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Pair a TV to a menu board', 'Pair a TV to a menu board: does ServOS do this and where is it? (Menu boards (TV))', 'Type the TV''s code or copy a screen link; Publish refreshes paired TVs live. Where to find it: Menu boards, Paired screens.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Layout and display', 'Layout and display: does ServOS do this and where is it? (Menu boards (TV))', 'Columns, follow timed menus, descriptions, allergens, prices, images, hide no price, sold out style, text size, price grid by size, fill the columns, seconds per page. Where to find it: Menu boards, Layout & display.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Packing', 'Packing: does ServOS do this and where is it? (Menu boards (TV))', 'Measured row heights, long categories continue with the header repeated, small categories never split, columns end level. Where to find it: Automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Design', 'Design: does ServOS do this and where is it? (Menu boards (TV))', 'Title, logo size, type sizes, line spacing, price pills, colours, font, footer, background image, lines under headings. Where to find it: Menu boards, Design.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Add ons and text panels', 'Add ons and text panels: does ServOS do this and where is it? (Menu boards (TV))', 'List option only sub items under a category; boxed text panels anywhere. Where to find it: Menu boards, Add ons and Text panel.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Page breaks', 'Page breaks: does ServOS do this and where is it? (Menu boards (TV))', 'Split a long board into rotating screens. Where to find it: Menu boards, Page break.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Marketing slides and image panels', 'Marketing slides and image panels: does ServOS do this and where is it? (Menu boards (TV))', 'Full screen images and video one after another; a rotating picture among the categories. Where to find it: Menu boards, Mode Marketing; Image panel.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Sold out on the board', 'Sold out on the board: does ServOS do this and where is it? (Menu boards (TV))', 'A red SOLD OUT pill or hidden, following the till within seconds. Where to find it: Automatic; Layout & display.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Portrait TV', 'Portrait TV: does ServOS do this and where is it? (Menu boards (TV))', 'Portrait or landscape, turn right or left. Where to find it: Menu boards, Orientation.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Playlist', 'Playlist: does ServOS do this and where is it? (Menu boards (TV))', 'A third kind of screen. Pick any of your boards (menus or marketing slideshows) in order, set how many seconds each one stays, and choose Fade, Slide or Cut. A marketing slideshow inside a playlist plays its slides through once, then the next board comes on. A price change or a sold out item updates the playlist without sending it back to the first board. Put the playlist on a TV exactly as you put a board on one. Where to find it: Back Office, Channels, Menu boards, Mode: Playlist.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'A TV keeps its pairing', 'A TV keeps its pairing: does ServOS do this and where is it? (Menu boards (TV))', 'A TV never drops to its pairing code because of one bad live update, a network drop, a failed read or a lost sign in; only Back Office can take a board down. A TV looks for the screen it already owns before making a new one. A grey note under a screen says when a TV kept its pairing or lost its sign in. Where to find it: automatic, Back Office, Menu boards.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Menu boards (TV)', false, false),
('doc', 'servos-features-2026-11-15', 'Customer facing display', 'Customer facing display: does ServOS do this and where is it? (Customer display)', 'A second screen shows ads when idle, the live order, follow the card reader, approved or declined; can mirror a till from another device. Where to find it: Customer display app or Sunmi rear screen; Device profiles.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer display', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty keypad on the display', 'Loyalty keypad on the display: does ServOS do this and where is it? (Customer display)', 'Customers type their mobile to collect points or stamps, see filled dots and a free drink ready, tap a reward; new numbers get a joining text; UK numbers checked. Where to find it: Customer display, Collect points.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer display', false, false),
('doc', 'servos-features-2026-11-15', 'Display branding and slideshow', 'Display branding and slideshow: does ServOS do this and where is it? (Customer display)', 'Own name, colours, logo and idle slideshow, separate from the kiosk. Where to find it: Device profiles, Customer display branding.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer display', false, false),
('doc', 'servos-features-2026-11-15', 'Readable brand colours', 'Readable brand colours: does ServOS do this and where is it? (Customer display)', 'A brand colour that cannot be read against the display''s background is replaced with one that can. Where to find it: automatic.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer display', false, false),
('doc', 'servos-features-2026-11-15', 'Line prices match the till', 'Line prices match the till: does ServOS do this and where is it? (Customer display)', 'A line with a paid option or an item discount shows the price the till charges, on the customer display and on the card reader''s screen. Where to find it: Customer display and reader.', 'Kitchen and fulfilment: KDS, printing, order screens, menu boards, display, notifications / Customer display', false, false),
('doc', 'servos-features-2026-11-15', 'Online ordering site', 'Online ordering site: does ServOS do this and where is it? (Online ordering)', 'A branded menu and basket on the venue''s own address for collection or delivery, now or later. Where to find it: <venue>.serv-os.app; Channels, Online Ordering.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Tipping on online orders', 'Tipping on online orders: does ServOS do this and where is it? (Online ordering)', 'Optional tip on discounted food and drink with venue set percentages. Where to find it: Online Ordering, Tipping on online orders.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Orders in advance', 'Orders in advance: does ServOS do this and where is it? (Online ordering)', 'Order for later days; shown as Tomorrow 12:45 everywhere and released on time. Where to find it: Online Ordering, Days ahead; Channels, Advance orders.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Timed menus online', 'Timed menus online: does ServOS do this and where is it? (Online ordering)', 'The storefront follows the menu schedule, rechecking every minute. Where to find it: Online Ordering, menu picker Automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Allergy filter online', 'Allergy filter online: does ServOS do this and where is it? (Online ordering)', 'Customers tick allergens and matching items are marked. Where to find it: Online menu, Allergy filter.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Customer warning message', 'Customer warning message: does ServOS do this and where is it? (Online ordering)', 'A venue notice on the ordering page. Where to find it: Online Ordering, Customer warning message.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Delivery on online orders', 'Delivery on online orders: does ServOS do this and where is it? (Online ordering)', 'Shows only when delivery is on, with the courier fee. Where to find it: Online Ordering, Allow delivery.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Pictures on options', 'Pictures on options: does ServOS do this and where is it? (Online ordering)', 'Options such as Box of 3 show the matching item''s photo. Where to find it: Online item sheet, automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Group ordering landing page', 'Group ordering landing page: does ServOS do this and where is it? (Online ordering)', 'One link for a group; pick a venue, then its online or catering site. Where to find it: /order/<group> and /cater/<group>.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Group ordering link look', 'Group ordering link look: does ServOS do this and where is it? (Online ordering)', 'The venue picker wears the look of the venue with the most complete Menu appearance; the Back Office card says which venue that is. Sub category items show under their parent section, the same as the till. Where to find it: Back Office, Online ordering.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Allergen chips everywhere', 'Allergen chips everywhere: does ServOS do this and where is it? (Online ordering)', 'Each allergen is a small chip with a warning mark and its name, the same on kiosk, online, QR, catering and the till. Chips include the size and options picked. A guest''s avoided allergens stand out; items are marked, never hidden. Colours follow each screen''s theme. Where to find it: product cards and sheets.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Menu languages online', 'Menu languages online: does ServOS do this and where is it? (Online ordering)', 'Guests with a phone in Spanish, French or Chinese see the menu in their language on online, QR, catering and the classic kiosk, with a switch back to English. Where to find it: Back Office, Online ordering, Menu languages.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Toast style ordering header', 'Toast style ordering header: does ServOS do this and where is it? (Online ordering)', 'Venue name, street address and Change location; the order type pill picks Collection or Delivery in place; a Collection from row and an ASAP, ready in row. Where to find it: online ordering page.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Order timing before the basket', 'Order timing before the basket: does ServOS do this and where is it? (Online ordering)', 'ASAP or Schedule for later from the header, with the checkout''s own slots, carried into checkout and back. Where to find it: online ordering header.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Change location', 'Change location: does ServOS do this and where is it? (Online ordering)', 'The company''s other online venues with their address; a warning when the basket would start again. Where to find it: online ordering header.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Menu search', 'Menu search: does ServOS do this and where is it? (Online ordering)', 'Find products by name, description or section, in the menu language; an icon on phones. Where to find it: online ordering category row.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Delivery address checked first', 'Delivery address checked first: does ServOS do this and where is it? (Online ordering)', 'Picking Delivery asks for the address and checks coverage, fee and minimum before the menu; not covered offers Collection or another venue; Add X more for delivery on the basket bar; checkout starts filled in. Where to find it: online ordering, Delivery.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Prefixed promo codes online', 'Prefixed promo codes online: does ServOS do this and where is it? (Online ordering)', 'Codes such as 5OFF- or BDAY- work at checkout, and a refused code says why. Where to find it: online checkout.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Online ordering', false, false),
('doc', 'servos-features-2026-11-15', 'QR table ordering', 'QR table ordering: does ServOS do this and where is it? (QR table ordering)', 'Scan a table code to order and pay; the order reaches the kitchen with the table. Where to find it: Online Ordering, QR ordering and Table identification.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Table QR codes', 'Table QR codes: does ServOS do this and where is it? (QR table ordering)', 'Download each table as JPEG, all as one PDF, or a generic code. Where to find it: Online Ordering, QR table side.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Pay now', 'Pay now: does ServOS do this and where is it? (QR table ordering)', 'Card, Apple Pay or Google Pay and the round is sent. Where to find it: QR checkout.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Open tab', 'Open tab: does ServOS do this and where is it? (QR table ordering)', 'A card hold opens a tab, rounds pool into one card, closed by the guest or by staff; a bill above the hold tries in full first then at the held amount with the shortfall reported; auto force close and left open surcharge. Where to find it: QR checkout, Open tab; Orders, QR section.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Join a tab with the table code', 'Join a tab with the table code: does ServOS do this and where is it? (QR table ordering)', 'A second phone enters the 6 digit code. Where to find it: QR page, Table code.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Welcome back', 'Welcome back: does ServOS do this and where is it? (QR table ordering)', 'A returning guest sees their open tab. Where to find it: QR page.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Tipping at the table and service charge', 'Tipping at the table and service charge: does ServOS do this and where is it? (QR table ordering)', 'QR tip percentages with No tip pre selected where service applies. Where to find it: Online Ordering, Tipping at the table.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'One order on its real table', 'One order on its real table: does ServOS do this and where is it? (QR table ordering)', 'An order paid on the phone is one order on the till, on its real table; it no longer also opens an unpaid floor table. Drinks ordered online, by QR or on catering show the product and the size on orders, kitchen screens and dockets. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'VAT on phone paid orders', 'VAT on phone paid orders: does ServOS do this and where is it? (QR table ordering)', 'A sale paid on the customer''s phone, with or without an automatic offer, books VAT on what the customer actually paid, the same rule as the till. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Counter collect QR', 'Counter collect QR: does ServOS do this and where is it? (QR table ordering)', '<venue>.serv-os.app/counter. Customers scan, order, pay and collect at the counter, with no table. Your own words and a card to print; only takes orders while open; the ready text says collect at the counter. Where to find it: Online ordering, QR ordering, Counter collect QR.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / QR table ordering', false, false),
('doc', 'servos-features-2026-11-15', 'Kiosk', 'Kiosk: does ServOS do this and where is it? (Self service kiosk)', 'Attract screen, eat in or take away, menu, basket, tip, loyalty, card and order number. Where to find it: ServOS Kiosk app or ?mode=kiosk; Channels, Kiosks.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'New kiosk design', 'New kiosk design: does ServOS do this and where is it? (Self service kiosk)', 'Five screens: start, menu with basket, Review and pay, card, done; light theme only. Where to find it: Kiosks, Settings, New kiosk design.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Eat in and tables', 'Eat in and tables: does ServOS do this and where is it? (Self service kiosk)', 'Table plan, Type a table number, Flag number, or Take away only. Where to find it: Kiosks, Settings, Eat in and tables.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Allergens on kiosk', 'Allergens on kiosk: does ServOS do this and where is it? (Self service kiosk)', 'Pick allergens, items marked Unsafe, optional forced confirmation before paying. Where to find it: Kiosks, Settings, Force allergen acknowledgement.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Menu languages and translations', 'Menu languages and translations: does ServOS do this and where is it? (Self service kiosk)', 'English, Spanish, French and Chinese; Claude translates menu text within 10 minutes of a change and the venue can correct it. Where to find it: Kiosk start screen; Kiosks, Settings, Menu languages.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty on kiosk', 'Loyalty on kiosk: does ServOS do this and where is it? (Self service kiosk)', 'Collect points by mobile with no code; spend a reward after a text code; full flow on the new design. Where to find it: Kiosks, Settings, Collect points and Loyalty sign in.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Text me when it''s ready', 'Text me when it''s ready: does ServOS do this and where is it? (Self service kiosk)', 'Leave a number and get a text when the order is marked ready. Where to find it: Kiosks, Settings; Review and pay screen.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Kiosk tipping', 'Kiosk tipping: does ServOS do this and where is it? (Self service kiosk)', 'Ask for a tip with up to three percentages and a pre selected choice. Where to find it: Kiosks, Kiosk tipping.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Look, brand and wording', 'Look, brand and wording: does ServOS do this and where is it? (Self service kiosk)', 'Brand name, logo, colours, theme, attract video, hero banners, button wording, idle timeout with Still there? Where to find it: Kiosks, Settings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Category photos', 'Category photos: does ServOS do this and where is it? (Self service kiosk)', 'Category tiles show a photo or a brand colour block. Where to find it: Kiosks, Settings, Show category photos.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Kiosk card refunds', 'Kiosk card refunds: does ServOS do this and where is it? (Self service kiosk)', 'Kiosk card sales carry their card payment, so the till can refund them to the card. If the pay screen reopens after a payment was approved but the order had not been saved, the kiosk finishes the order with that payment and never charges twice. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Counter collect tile', 'Counter collect tile: does ServOS do this and where is it? (Self service kiosk)', 'A third tile next to Eat in and Take away, with your own words, per kiosk. It books as eat in with no table, and the done screen says collect at the counter. Where to find it: Kiosk settings, Customer flow, Counter collect.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'No wait shown', 'No wait shown: does ServOS do this and where is it? (Self service kiosk)', 'Type 0 in Average wait time and the wait line leaves that kiosk''s start screen, even when online and QR quote a wait. Where to find it: Kiosk settings, Average wait time.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Keyboard never covers typing', 'Keyboard never covers typing: does ServOS do this and where is it? (Self service kiosk)', 'The notes box and the Add button move above the screen keyboard, and every box a customer types in scrolls into view. Where to find it: Kiosk.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Dietary words on the kiosk', 'Dietary words on the kiosk: does ServOS do this and where is it? (Self service kiosk)', 'Vegetarian, Vegan, Gluten free and Dairy free on menu cards and item screens, a size''s own tags first, in the kiosk language. Where to find it: Kiosk.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Cancel stops the reader', 'Cancel stops the reader: does ServOS do this and where is it? (Self service kiosk)', 'Cancelling a live card prompt aborts it on the Adyen reader. Where to find it: Kiosk card payment.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Self service kiosk', false, false),
('doc', 'servos-features-2026-11-15', 'Catering site', 'Catering site: does ServOS do this and where is it? (Catering and ezCater)', 'Event date and time, lead time, closed dates, daily capacity, minimum, per item limits, for collection, takeaway or delivery. Where to find it: /catering; Channels, Catering ordering.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'Catering checkout', 'Catering checkout: does ServOS do this and where is it? (Catering and ezCater)', 'Pay now by card or pay later, with tips. Where to find it: Catering ordering, Checkout options.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'Advance orders', 'Advance orders: does ServOS do this and where is it? (Catering and ezCater)', 'Every catering and later day order grouped by day, ezCater labelled. Where to find it: Channels, Advance orders.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'ezCater connection', 'ezCater connection: does ServOS do this and where is it? (Catering and ezCater)', 'Paste the code, pick the caterer location, set auto accept; one connection per company; shown to dollar venues. Where to find it: Channels, 3rd Party orders.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'ezCater item matching and menu sync', 'ezCater item matching and menu sync: does ServOS do this and where is it? (Catering and ezCater)', 'Match each ezCater item to your product once; Sync ezCater menu. Where to find it: 3rd Party orders, ezCater item matching.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'ezCater orders', 'ezCater orders: does ServOS do this and where is it? (Catering and ezCater)', 'Arrive paid, held as Awaiting ezCater acceptance, with alerts for late changes or cancels. Where to find it: Advance orders and kitchen screens.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'ezCater orders as sales', 'ezCater orders as sales: does ServOS do this and where is it? (Catering and ezCater)', 'An accepted ezCater order is booked as a sale with ezCater''s own figures, so it reaches reports, the Tax report, Xero and stock. A change or cancel updates it; a sold out item alerts staff. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'Catering pay now on Adyen', 'Catering pay now on Adyen: does ServOS do this and where is it? (Catering and ezCater)', 'The catering checkout takes card and wallets in page on Adyen. Where to find it: Catering page.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Catering and ezCater', false, false),
('doc', 'servos-features-2026-11-15', 'Booking widget', 'Booking widget: does ServOS do this and where is it? (Table bookings)', 'Mobile first page in the venue''s branding, embeddable anywhere; slots respect the pacing cap. Where to find it: /book; Channels, Table bookings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Packages and events', 'Packages and events: does ServOS do this and where is it? (Table bookings)', 'Sell experiences with a direct link, menu style detail and per event terms. Where to find it: Booking page; Channels, Packages & events.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Pre orders and menu choices', 'Pre orders and menu choices: does ServOS do this and where is it? (Table bookings)', 'A dish per course per guest at booking or by link, with deadlines and reminders; lands on the kitchen ticket when seated. Where to find it: Booking page; Diary, Send pre order link.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Deposits, prepay and card holds', 'Deposits, prepay and card holds: does ServOS do this and where is it? (Table bookings)', 'Prepay charges in full, deposits at booking, plain bookings hold a card; confirmed only after Adyen approves with the table held 20 minutes. Where to find it: Table bookings, Card capture.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Booking terms', 'Booking terms: does ServOS do this and where is it? (Table bookings)', 'Venue wide terms shown as By booking you agree to. Where to find it: Table bookings, Booking terms.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Online booking blocks', 'Online booking blocks: does ServOS do this and where is it? (Table bookings)', 'Block days and keep chosen tables off the widget. Where to find it: Table bookings, Blocked days.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Booking rules', 'Booking rules: does ServOS do this and where is it? (Table bookings)', 'Turn times by party size, join groups, max tables, wasted seat tolerance, pacing cap with manager override, protect large tables. Where to find it: Table bookings; Floor plan join groups.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Bookings host stand', 'Bookings host stand: does ServOS do this and where is it? (Table bookings)', 'Tablet app with Service, Diary, Floor, Book, Events, Reports and Widget, with guest search. Where to find it: ServOS Bookings app; Table bookings, Pair a host stand.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Seat now opens the till tab', 'Seat now opens the till tab: does ServOS do this and where is it? (Table bookings)', 'Guest, allergens, pre orders and prepaid package land on the check; no shows and departures can be undone. Where to find it: Host stand, Seat now.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Edit a booking', 'Edit a booking: does ServOS do this and where is it? (Table bookings)', 'Change date, time, covers, guest, allergens, note or tables; free and taken tables are shown and every refusal is said in words. The server checks it so two devices never double book. Where to find it: Host stand, Edit; till; Back Office, Table bookings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Drag on the Timeline', 'Drag on the Timeline: does ServOS do this and where is it? (Table bookings)', 'Press and hold a booking and drag it to another table or time; green when free, red when not, then Move or Keep. Where to find it: Host stand, Timeline.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Guest''s own booking page', 'Guest''s own booking page: does ServOS do this and where is it? (Table bookings)', 'Every booking gets a link where the guest adds it to a calendar, changes date, time or party size, or cancels, up to the cancellation window. Where to find it: the guest''s link.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Booking messages', 'Booking messages: does ServOS do this and where is it? (Table bookings)', 'A confirmation with the guest''s link for every booking however it was made, reminders the day before and 2 hours before, and a message on any change or cancel. Failed sends retry 3 times and show on the booking card. Where to find it: Booking card, Messages; Back Office, Messages, Bookings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Service periods', 'Service periods: does ServOS do this and where is it? (Table bookings)', 'Lunch and dinner per day with a last seating, closed days and dates, blocked times and online notice. Every screen and the database follow them; walk ins are never refused. Where to find it: Host stand, Rules; Back Office, Table bookings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Prepaid money on the bill', 'Prepaid money on the bill: does ServOS do this and where is it? (Table bookings)', 'A seated booking''s prepay or deposit shows on the till as a payment and To pay shows the rest. Money not used is kept on the booking to give back. Cashing off the table marks the booking departed. Where to find it: Till and host stand.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Refunds, pay links and no show charges', 'Refunds, pay links and no show charges: does ServOS do this and where is it? (Table bookings)', 'Refund all or part from the booking card (manager PIN); text a link to pay a deposit or save a card; charge a saved card once for a no show or late cancel. Nothing refunds by itself. Where to find it: Host stand, booking card; Back Office, Table bookings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Requests inbox', 'Requests inbox: does ServOS do this and where is it? (Table bookings)', 'Large party requests from the booking page land under Requests in the top bar, with Accept, Call and Decline. Where to find it: Host stand.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Guest tags', 'Guest tags: does ServOS do this and where is it? (Table bookings)', 'VIP, Regular and the visit count show on the booking card, the Book screen and the till''s check header. Where to find it: Host stand and till.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Host stand on the venue clock', 'Host stand on the venue clock: does ServOS do this and where is it? (Table bookings)', 'Every time is the venue''s, the diary refreshes itself every minute and on wake, the floor reads the server every 30 seconds, and the PIN user''s name goes on what they do. Where to find it: Host stand.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Fairer booking page', 'Fairer booking page: does ServOS do this and where is it? (Table bookings)', 'Single tables can be booked, greyed times say why, the party picker stops at the pacing cap, and a time that has just gone says so. Where to find it: Booking page.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Table bookings', false, false),
('doc', 'servos-features-2026-11-15', 'Tables Ready host stand', 'Tables Ready host stand: does ServOS do this and where is it? (Tables Ready (waitlist))', 'Add a party by phone, quote a wait, seat onto a fitting table. Where to find it: ServOS Waitlist app; Channels, Tables Ready.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Tables Ready (waitlist)', false, false),
('doc', 'servos-features-2026-11-15', 'Guest self service', 'Guest self service: does ServOS do this and where is it? (Tables Ready (waitlist))', 'Join from a QR link and watch the wait with On my way and Cancel. Where to find it: Tables Ready, Guest self service.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Tables Ready (waitlist)', false, false),
('doc', 'servos-features-2026-11-15', 'Waitlist text messages', 'Waitlist text messages: does ServOS do this and where is it? (Tables Ready (waitlist))', 'Editable texts at each step; reply C to cancel, OK to confirm, STOP to opt out. Where to find it: Tables Ready, Text messages.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Tables Ready (waitlist)', false, false),
('doc', 'servos-features-2026-11-15', 'Quote rules', 'Quote rules: does ServOS do this and where is it? (Tables Ready (waitlist))', 'Safety buffer, maximum, rounding, turn time by party size with learned times alongside. Where to find it: Tables Ready, Quote rules.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Tables Ready (waitlist)', false, false),
('doc', 'servos-features-2026-11-15', 'Seating zones and branding', 'Seating zones and branding: does ServOS do this and where is it? (Tables Ready (waitlist))', 'Zones guests can prefer and the look of guest pages. Where to find it: Tables Ready, Seating zones, Branding.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Tables Ready (waitlist)', false, false),
('doc', 'servos-features-2026-11-15', 'Wait timer against the quote', 'Wait timer against the quote: does ServOS do this and where is it? (Tables Ready (waitlist))', 'Over by 6 min in amber, then red, with what to tell the guest; Seat on T8 when a fitting table is free, never one booked soon. Where to find it: Tables Ready host stand.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Tables Ready (waitlist)', false, false),
('doc', 'servos-features-2026-11-15', 'HubRise (Deliveroo, Uber Eats, Just Eat)', 'HubRise (Deliveroo, Uber Eats, Just Eat): does ServOS do this and where is it? (Delivery platforms)', 'Orders arrive on tills and screens with the app name and code; menu and sold out sync back; auto accept and prep time. Where to find it: Channels, Delivery channels (HubRise).', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Delivery platforms', false, false),
('doc', 'servos-features-2026-11-15', 'Stuart courier', 'Stuart courier: does ServOS do this and where is it? (Delivery platforms)', 'Each venue connects its own account; live pricing or flat fee, subsidy, radius, fallback and a tracking text; staff request or retry a courier from Orders and show a QR for the live map. Where to find it: Channels, Delivery; Orders screen.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Delivery platforms', false, false),
('doc', 'servos-features-2026-11-15', 'Deliveries (live) board', 'Deliveries (live) board: does ServOS do this and where is it? (Delivery platforms)', 'Status, courier, tracking, timeline and margin per delivery, with cancel. Where to find it: Channels, Deliveries (live).', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Delivery platforms', false, false),
('doc', 'servos-features-2026-11-15', 'Menu changes reach the apps by themselves', 'Menu changes reach the apps by themselves: does ServOS do this and where is it? (Delivery platforms)', 'A Menu Manager save or a multi site publish reaches Deliveroo, Uber Eats and Just Eat a few minutes later, and an item sold out by its daily count within 2 minutes. Where to find it: automatic, once Push menu has been pressed.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Delivery platforms', false, false),
('doc', 'servos-features-2026-11-15', 'No courier at US venues yet', 'No courier at US venues yet: does ServOS do this and where is it? (Delivery platforms)', 'Stuart is not offered at a US venue; the screens say delivery orders are driven by your own staff and HubRise copy says your delivery apps. UK unchanged. Where to find it: Delivery settings at a US venue.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Delivery platforms', false, false),
('doc', 'servos-features-2026-11-15', 'Your WiFi page', 'Your WiFi page: does ServOS do this and where is it? (Guest WiFi)', 'Branded sign up page with name, email, phone, date of birth, local and marketing opt in; loyalty sign up offer; legal links; QR. Where to find it: Back Office, Customers, WiFi, Your page.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Guest WiFi', false, false),
('doc', 'servos-features-2026-11-15', 'UniFi setup', 'UniFi setup: does ServOS do this and where is it? (Guest WiFi)', 'Connect with a Site Manager API key and follow the step by step guide with copy buttons; time online per guest. Where to find it: WiFi, Setup.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Guest WiFi', false, false),
('doc', 'servos-features-2026-11-15', 'Fixed WiFi front door', 'Fixed WiFi front door: does ServOS do this and where is it? (Guest WiFi)', '<venue>.wifi.serv-os.app served from one fixed address so UniFi stops blocking the page. Where to find it: Automatic; shown in the setup guide.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Guest WiFi', false, false),
('doc', 'servos-features-2026-11-15', 'WiFi dashboard', 'WiFi dashboard: does ServOS do this and where is it? (Guest WiFi)', 'Sign ups, returning devices, opt ins, segments and CSV; guests feed the CRM and WiFi automations. Where to find it: WiFi, Dashboard.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Guest WiFi', false, false),
('doc', 'servos-features-2026-11-15', 'The sign in page scrolls', 'The sign in page scrolls: does ServOS do this and where is it? (Guest WiFi)', 'On a small phone the Connect button can always be reached; the review page and the waitlist join page had the same fix. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Guest WiFi', false, false),
('doc', 'servos-features-2026-11-15', 'Customer review card', 'Customer review card: does ServOS do this and where is it? (Reviews)', 'A public rate us page; happy guests go to Google, unhappy ones write to the manager; title, intro, images, button style, QR. Where to find it: /review; Customers, Reviews, Your card.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Rating routing', 'Rating routing: does ServOS do this and where is it? (Reviews)', 'At or above the threshold is public, below stays private; enforced on the server. Where to find it: Reviews, Settings, Internal emphasis threshold.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Private feedback and recovery reply', 'Private feedback and recovery reply: does ServOS do this and where is it? (Reviews)', 'Under threshold feedback lands with the manager and the reply goes to the guest by SMS or email. Where to find it: Review card; Approvals.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Review asks', 'Review asks: does ServOS do this and where is it? (Reviews)', 'Automatic one tap invites after a table closes or a collection, with send window, cap, do not re ask and STOP handling. Where to find it: Reviews, Get reviews.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Google Business Profile connection', 'Google Business Profile connection: does ServOS do this and where is it? (Reviews)', 'One click connect; reviews sync in and approved replies post back. Where to find it: Reviews, Settings, Connected platforms.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Other platforms by listing URL', 'Other platforms by listing URL: does ServOS do this and where is it? (Reviews)', 'TripAdvisor, Facebook and Yelp links on the card. Where to find it: Reviews, Settings.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Approvals queue with AI drafts', 'Approvals queue with AI drafts: does ServOS do this and where is it? (Reviews)', 'Every review with a Claude drafted reply in the brand voice; approve, edit, regenerate, send; auto draft on or off. Where to find it: Reviews, Approvals; Settings, AI replies.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Reviews dashboard', 'Reviews dashboard: does ServOS do this and where is it? (Reviews)', 'Average, total, public and private, needs reply, distribution, by source, ask funnel. Where to find it: Reviews, Dashboard.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Review asks link to your ServOS address', 'Review asks link to your ServOS address: does ServOS do this and where is it? (Reviews)', 'The automatic asks and Send a test link to the venue''s own address, for example habitum.serv-os.app/review, instead of a temporary one. Where to find it: Reviews, Review asks.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Reviews', false, false),
('doc', 'servos-features-2026-11-15', 'Website builder', 'Website builder: does ServOS do this and where is it? (Website builder)', 'A public website at <slug>.sites.serv-os.app built from the venue''s branding, menu, hours and locations. Where to find it: Channels, Appearance, Website builder.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'AI designer', 'AI designer: does ServOS do this and where is it? (Website builder)', 'Build me a website builds every page in stages; talk to it to change any page; it reads sites you link and screenshots you attach, never copying their words or photos. Where to find it: Website builder, Designer.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Pages and blocks', 'Pages and blocks: does ServOS do this and where is it? (Website builder)', 'Hero and slideshow, live menu, specials, order bar, opening hours, find us with nearest shop and postcode search, loyalty, gift cards, book a table, waitlist, latest posts, text, heading, image, rows of 1 to 4 columns, gallery, button, FAQ, Instagram, divider and spacer; a width per block; drafts save themselves; photo uploads; a link picker. Where to find it: Website builder, page editor.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Live menu on the site', 'Live menu on the site: does ServOS do this and where is it? (Website builder)', 'The same menu, prices, photos and allergen words as online, following the timed menu; an 86 item comes off within a second; pick the menu, categories and venue; a venue switch on group sites; tap an item for its photo and details. Where to find it: Live menu block.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Ordering from the site', 'Ordering from the site: does ServOS do this and where is it? (Website builder)', 'Order, Catering and Book buttons open the venue''s own pages in the same tab, no frames; a group site asks which venue first. Where to find it: website buttons.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Header, navigation and look', 'Header, navigation and look: does ServOS do this and where is it? (Website builder)', 'Brand mark and logo size, header button, sticky header, menu items with drop downs, page, card and text colours, a brand name for cards, footer and search results. Where to find it: Branding and domain; Look.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Your own domain', 'Your own domain: does ServOS do this and where is it? (Website builder)', 'The exact records to add with copy buttons, SSL state, green when live; the free address always works. Where to find it: Branding and domain.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Blog', 'Blog: does ServOS do this and where is it? (Website builder)', 'Posts with a cover photo, tags, drafts and publish; the designer can write one. Where to find it: Website builder, Posts.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Built for Google', 'Built for Google: does ServOS do this and where is it? (Website builder)', 'Every page served as real HTML with titles, descriptions, a sitemap, robots and structured data for the venue, locations, menu and posts. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Publish, history and terms', 'Publish, history and terms: does ServOS do this and where is it? (Website builder)', 'Every publish kept with one press restore, Take offline, 30 minute preview links, and publishing terms accepted on the first publish. Where to find it: Website builder, Publish.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Venues placed on the map', 'Venues placed on the map: does ServOS do this and where is it? (Website builder)', 'Venues without coordinates are found from their address automatically. Where to find it: automatic.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Gift and loyalty card pictures', 'Gift and loyalty card pictures: does ServOS do this and where is it? (Website builder)', 'Upload your own card design, with your own title and label or no words. Where to find it: Gift cards and Loyalty blocks.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Reviews block', 'Reviews block: does ServOS do this and where is it? (Website builder)', 'Drag a Reviews block onto any page and it shows the Review Manager''s public reviews (stars, words, first name and last initial, date, source); each block picks how many and the minimum stars. No switch. Where to find it: Website builder, blocks.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Count visits and Website report', 'Count visits and Website report: does ServOS do this and where is it? (Website builder)', 'One switch, Count visits (on; one small ping per page, no cookie, a daily hashed visitor key). Website report shows visits and visitors per day on the venue''s own days, top pages, where people came from, utm sources and the visits that followed a campaign link. Where to find it: Website builder, Overview; Customers, Website report.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Website report by site', 'Website report by site: does ServOS do this and where is it? (Website builder)', 'A company with more than one website picks the site, with a By site table. Where to find it: Customers, Website report.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Website builder', false, false),
('doc', 'servos-features-2026-11-15', 'Customer app', 'Customer app: does ServOS do this and where is it? (Customer app)', 'A native iPhone and Android app, one app themed per organisation, built from the same loyalty, ordering, stamps and gift card data as the loyalty portal. Coffee Boy is the first app, on TestFlight. Where to find it: App Store and Google Play, one app per organisation.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Customer app', false, false),
('doc', 'servos-features-2026-11-15', 'App branding', 'App branding: does ServOS do this and where is it? (Customer app)', 'The app''s name and ids, the two logos and the icon, the accent colour with a contrast readout (a pale accent is corrected for text and buttons and the tab says which shade), display and body typefaces (nine faces: Montserrat, Poppins, Bebas Neue, Inter, DM Sans and the serif and grotesk set), corner radius, money and language, the modules the app ships with, the privacy, support and terms links and a live phone preview. Publish theme reaches installed apps on their next launch. Where to find it: Channels, Appearance, App branding.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Customer app', false, false),
('doc', 'servos-features-2026-11-15', 'Sign in that lasts', 'Sign in that lasts: does ServOS do this and where is it? (Customer app)', 'One code by text, then signed in for 180 days; the key rotates on every refresh and a stolen old key ends every sign in in that chain. Sign out ends it. Where to find it: Customer app.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Customer app', false, false),
('doc', 'servos-features-2026-11-15', 'Delete my account', 'Delete my account: does ServOS do this and where is it? (Customer app)', 'In the app; personal data wiped, the membership and stamps ended, every app sign in ended, while sales and gift ledgers stay for the venue''s books. Where to find it: Customer app, account.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Customer app', false, false),
('doc', 'servos-features-2026-11-15', 'Venues and hours in the app', 'Venues and hours in the app: does ServOS do this and where is it? (Customer app)', 'The organisation''s live venues with opening hours, open or closed right now and the web ordering link. Where to find it: Customer app.', 'Customer channels: online, QR, kiosk, catering, bookings, waitlist, delivery, WiFi, reviews / Customer app', false, false),
('doc', 'servos-features-2026-11-15', 'Customer list', 'Customer list: does ServOS do this and where is it? (Customer records)', 'Every customer across the company with Loyalty, Points, Spend and Last visit; search asks the database so all 8,000 plus are findable. Where to find it: Back Office, Customers, Customer list.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Customer profile', 'Customer profile: does ServOS do this and where is it? (Customer records)', 'Lifetime spend, visits, loyalty balance and code, stamp cards, per location stats, orders and gift cards; edit name, phone, email, notes, allergens, marketing. Where to find it: Customers, click a customer.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Notes and allergens on the profile', 'Notes and allergens on the profile: does ServOS do this and where is it? (Customer records)', 'Saved allergens apply as the till filter the moment the customer goes on a table order. Where to find it: Customers, Allergens; till automatic.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Merge with another customer', 'Merge with another customer: does ServOS do this and where is it? (Customer records)', 'See both side by side, pick the phone to keep, merge stamps, points, orders and visits. Where to find it: Profile footer, Merge.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Delete customer', 'Delete customer: does ServOS do this and where is it? (Customer records)', 'Soft delete for right to be forgotten; order history stays for audit. Where to find it: Profile footer, Delete.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Export CSV', 'Export CSV: does ServOS do this and where is it? (Customer records)', 'The filtered list with marketing opt in. Where to find it: Customers, Export CSV.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Insights and cross location', 'Insights and cross location: does ServOS do this and where is it? (Customer records)', 'Brand VIPs, Top per location, Multi location customers, Cross sell candidates, Dormant VIPs. Where to find it: Customers, Insights & cross location.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'One phone rule', 'One phone rule: does ServOS do this and where is it? (Customer records)', 'Every spelling of a UK mobile is the same customer on till, online, QR, kiosk, loyalty and import. Where to find it: Automatic.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Automatic join on a matching email', 'Automatic join on a matching email: does ServOS do this and where is it? (Customer records)', 'A sign up with an email already on a record with no phone joins it with no question; the owner gets one notice email. Where to find it: Automatic on till and portal.', 'Customers, loyalty and marketing / Customer records', false, false),
('doc', 'servos-features-2026-11-15', 'Import customers', 'Import customers: does ServOS do this and where is it? (Customer records)', 'CSV of loyalty members with stamps, points and gift balances; preview writes nothing, refused rows download with a reason, running twice changes nothing. Where to find it: Admin portal, Import customers (ServOS staff only).', 'Customers, loyalty and marketing / Customer records', true, false),
('doc', 'servos-features-2026-11-15', 'Loyalty programme switches', 'Loyalty programme switches: does ServOS do this and where is it? (Loyalty)', 'Points and Stamp cards on or off independently, with portal links. Where to find it: Customers, Loyalty.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Points settings', 'Points settings: does ServOS do this and where is it? (Loyalty)', 'Points per pound, rounding, expiry, earning rules and bonus points for registration, birthday and referral. Where to find it: Loyalty, Points settings.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Rewards catalog', 'Rewards catalog: does ServOS do this and where is it? (Loyalty)', 'Fixed, percent, free item or category, free delivery or custom, each with a points cost. Where to find it: Loyalty, Rewards.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Stamp card programs', 'Stamp card programs: does ServOS do this and where is it? (Loyalty)', 'Buy N get one free with eligible items and what earns a stamp; saved for every site. Where to find it: Loyalty, Stamp Cards.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty tiers', 'Loyalty tiers: does ServOS do this and where is it? (Loyalty)', 'Named tiers with minimum points, multiplier and colour. Where to find it: Loyalty, Tiers.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Members', 'Members: does ServOS do this and where is it? (Loyalty)', 'Totals, search and an adjust points box with reason. Where to find it: Loyalty, Members.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Adjust stamps', 'Adjust stamps: does ServOS do this and where is it? (Loyalty)', 'Add or remove stamps or whole cards with a required reason, written to the ledger. Where to find it: Customer profile, Stamp cards, Adjust.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty on online ordering and QR', 'Loyalty on online ordering and QR: does ServOS do this and where is it? (Loyalty)', 'Online checkout signs a member in with a text code; QR orders carry the member. Where to find it: Online and QR checkout.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Customer loyalty portal', 'Customer loyalty portal: does ServOS do this and where is it? (Loyalty)', 'Sign in with a text code to see points, tier, rewards, stamps, gift balance, history and profile; sign up page. Where to find it: /account and /account/register.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Apple Wallet and Google Wallet card', 'Apple Wallet and Google Wallet card: does ServOS do this and where is it? (Loyalty)', 'Add the loyalty card from the portal or online checkout. Where to find it: Customer portal.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Welcome text and email', 'Welcome text and email: does ServOS do this and where is it? (Loyalty)', 'A branded welcome with the account link the first time a customer joins. Where to find it: Automatic; Messages, Loyalty Welcome.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Company wide loyalty', 'Company wide loyalty: does ServOS do this and where is it? (Loyalty)', 'Points, stamps, rewards, memberships and gift cards are one account across every site. Where to find it: Automatic for multi site companies.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Code texts in the venue''s own name', 'Code texts in the venue''s own name: does ServOS do this and where is it? (Loyalty)', 'Every venue gets its own text service at set up or rename, so a sign in code is never sent under another venue''s name. The page shows Ready, or the reason with a Fix button; a nightly check repairs the rest. Where to find it: Back Office, Messages, Verification code.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty app shows what you collect', 'Loyalty app shows what you collect: does ServOS do this and where is it? (Loyalty)', 'The home page says You collect: Stamps, Points or both. A stamps only business shows the stamp card (4 of 10, 6 more for your Free Drink) and never 0 points. The header shows the member code and the last 4 digits of the phone. Where to find it: Customer loyalty app.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Same stamp words everywhere', 'Same stamp words everywhere: does ServOS do this and where is it? (Loyalty)', 'Cards finished, Rewards used and Ready now, in Back Office and the app. With points off the points rows are gone. Where to find it: Back Office, customer details; loyalty app.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Earn on every channel', 'Earn on every channel: does ServOS do this and where is it? (Loyalty)', 'A phone number left on QR, online or catering earns stamps and points like the till, QR tabs earn when paid, and delivery app orders earn for the customer''s own phone. Where to find it: automatic.', 'Customers, loyalty and marketing / Loyalty', false, false),
('doc', 'servos-features-2026-11-15', 'Offers', 'Offers: does ServOS do this and where is it? (Promotions)', 'Reusable offers: money off, percent off, free item, free delivery or bonus points with minimum spend, dates and uses per customer. Where to find it: Customers, Promotions, Offers.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'One time promo codes', 'One time promo codes: does ServOS do this and where is it? (Promotions)', 'Issued per customer by campaigns and automations, redeemed once, race safe; look up and void. Where to find it: Promotions, Look up a code.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'Auto discount rules', 'Auto discount rules: does ServOS do this and where is it? (Promotions)', 'Buy X get Y, bundles and meal deals that apply by themselves on till, kiosk, online and QR, with days, times and dates; happy hour is a time of day rule. Where to find it: Menu, Discounts, Auto discount rules.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'Promo codes follow their offer', 'Promo codes follow their offer: does ServOS do this and where is it? (Promotions)', 'Category, free item, free delivery and bonus points codes work on every channel, checked on the goods after deals. A code comes back when its sale is fully refunded. Where to find it: Till, kiosk, online, QR, catering.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'Buy X, discount the lot', 'Buy X, discount the lot: does ServOS do this and where is it? (Promotions)', 'A new automatic deal, for example 6 donuts, 15% off all 6; with 12 it counts twice. Works on till, kiosk, online and QR; an item never gets two automatic deals. Where to find it: Menu, Discounts, Auto discount rules.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'Deals in plain words', 'Deals in plain words: does ServOS do this and where is it? (Promotions)', 'The Buy X get Y editor says the rule as one sentence as you type (buys 3 Donuts at full price, then the next 1 is 10% off), and the list of rules says the same. Where to find it: Menu, Discounts.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'Which sites on offers', 'Which sites on offers: does ServOS do this and where is it? (Promotions)', 'Where an offer''s codes work, All sites or a list; the till refuses a code at a venue outside the list and a list naming only sites that are not yours is refused on the server. Where to find it: Promotions, an offer, Which sites.', 'Customers, loyalty and marketing / Promotions', false, false),
('doc', 'servos-features-2026-11-15', 'Segments', 'Segments: does ServOS do this and where is it? (Marketing)', 'Prebuilt audiences with live counts plus your own rules on spend, visits, recency, birthday, source, consent and more. Where to find it: Customers, Segments.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Campaigns', 'Campaigns: does ServOS do this and where is it? (Marketing)', 'Birthday, win back, recurring, sales behind forecast or one off; email or SMS, offer code, exclusions, A/B subject, test send, runs. Where to find it: Customers, Campaigns.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Email builder', 'Email builder: does ServOS do this and where is it? (Marketing)', 'Block based email with your branding and a preview. Where to find it: Campaigns and Quick send.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Quick send', 'Quick send: does ServOS do this and where is it? (Marketing)', 'A one off email or SMS to an audience with an optional code; no consent means skipped. Where to find it: Customers, Quick send.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Automations', 'Automations: does ServOS do this and where is it? (Marketing)', 'Multi step drips on sign up, birthday, segment entry, WiFi connect or manual. Where to find it: Customers, Automations.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Marketing report', 'Marketing report: does ServOS do this and where is it? (Marketing)', 'Sent, delivered, opened, clicked, codes redeemed, discount given, revenue attributed, by campaign, offer and automation. Where to find it: Customers, Marketing report.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Marketing compliance', 'Marketing compliance: does ServOS do this and where is it? (Marketing)', 'The suppression list across email and SMS with manual blocks; every send checks consent and carries unsubscribe. Where to find it: Customers, Marketing compliance.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Customer preference centre', 'Customer preference centre: does ServOS do this and where is it? (Marketing)', 'A page from any marketing email to switch email or SMS on or off. Where to find it: Link in marketing emails.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Email domain', 'Email domain: does ServOS do this and where is it? (Marketing)', 'Send from the venue''s own domain with DNS records, verify, from and reply to. Where to find it: Settings, Email domain.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Sending engine', 'Sending engine: does ServOS do this and where is it? (Marketing)', 'One sender for email and SMS that resolves the person, enforces consent, renders merge tags and logs every message. Where to find it: Behind Campaigns, Quick send and Automations.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Big sends go out', 'Big sends go out: does ServOS do this and where is it? (Marketing)', 'Emails in batches of 100 that carry on by themselves until done, Continue sending for a stopped send, nobody sent twice. Where to find it: Customers, Quick send.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Promo code by automation', 'Promo code by automation: does ServOS do this and where is it? (Marketing)', 'Trigger Form submitted and a Send a promo code step by email or text, only with the marketing tick, one code per person per form, never for an offer they already used. Where to find it: Customers, Automations.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'The organisation owns, the sites use', 'The organisation owns, the sites use: does ServOS do this and where is it? (Marketing)', 'Customers, loyalty, segments, campaigns, automations, offers, forms and the website belong to the organisation and every site sees them whichever venue Back Office is signed in to. A Sites control at the top of Promotions, Segments, Campaigns, Quick send, Forms, Automations, Marketing report and Website report shows All sites or one site, remembered per login; on one site the lists show what is aimed there, new things start aimed there and counts are that site''s customers. A site badge on every campaign, automation and offer row. Nothing changes for a one site company. Where to find it: Customers, Marketing, Sites control.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Any and all groups in segments', 'Any and all groups in segments: does ServOS do this and where is it? (Marketing)', 'A condition can be a group matched the other way round (all inside any, any inside all) to three levels, so VIPs who ordered pizza OR lapsed customers with an email is one segment. Old segments open and count exactly as before. Where to find it: Segments, Add group.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Segment by item ordered', 'Segment by item ordered: does ServOS do this and where is it? (Marketing)', 'Ordered an item, or anything in a category, in the last N days, on every channel and every venue, with item and category pickers from the company menu. Where to find it: Segments, conditions.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty conditions in segments', 'Loyalty conditions in segments: does ServOS do this and where is it? (Marketing)', 'Points balance, points to next reward, stamps on card, stamps to go, rewards ready, member or not and tier, decided from the same rows the loyalty app reads. Where to find it: Segments, conditions.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Where they visit', 'Where they visit: does ServOS do this and where is it? (Marketing)', 'Visited a venue (which venues, optionally in the last N days) and Home venue (the venue they visit most), nestable with every other rule. Where to find it: Segments, Where they visit.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty merge tags', 'Loyalty merge tags: does ServOS do this and where is it? (Marketing)', 'Points_balance, points_to_next_reward, next_reward, tier, stamps_earned, stamps_target, stamps_to_go, stamp_reward and rewards_ready in emails and texts, filled per customer at send time, with sample values in the builder. Where to find it: Email builder, merge tags.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Link clicks tracked', 'Link clicks tracked: does ServOS do this and where is it? (Marketing)', 'Every link in a campaign or automation email goes through a signed ServOS redirect that records the click and moves the message to Clicked, then sends the person on with utm tags. Marketing report has a Link clicks card per campaign, automation and link, and the customer record lists what they clicked. Where to find it: Marketing report, Link clicks; customer profile.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Which sites on campaigns and automations', 'Which sites on campaigns and automations: does ServOS do this and where is it? (Marketing)', 'Tick the venues, default All sites; the engine narrows the audience by venue so a Leeds offer never reaches a Huddersfield only customer. Where to find it: Campaigns and Automations, Which sites.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Marketing report by site', 'Marketing report by site: does ServOS do this and where is it? (Marketing)', 'Sent, opened and clicked by the customer''s home venue, redeemed, discount and revenue by the venue where the code was used, with a site picker that shows each campaign and automation for that venue. Where to find it: Marketing report, By site.', 'Customers, loyalty and marketing / Marketing', false, false),
('doc', 'servos-features-2026-11-15', 'Message templates', 'Message templates: does ServOS do this and where is it? (Messages)', 'Edit every transactional SMS and email: orders, gift cards, tables, receipts, loyalty and bookings, with merge tags, preview and reset. Where to find it: Back Office, Customers, Messages.', 'Customers, loyalty and marketing / Messages', false, false),
('doc', 'servos-features-2026-11-15', 'SMS sending', 'SMS sending: does ServOS do this and where is it? (Messages)', 'Transactional texts through Twilio logged per location; says Tomorrow for tomorrow''s orders. Where to find it: Automatic.', 'Customers, loyalty and marketing / Messages', false, false),
('doc', 'servos-features-2026-11-15', 'Issue a new gift card', 'Issue a new gift card: does ServOS do this and where is it? (Gift cards)', 'Amount, recipient, expiry and note; code shown once and sent. Where to find it: Customers, Gift cards.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Bulk create gift cards', 'Bulk create gift cards: does ServOS do this and where is it? (Gift cards)', 'Up to 500 at one amount under a batch name. Where to find it: Gift cards, Bulk create.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Import gift cards', 'Import gift cards: does ServOS do this and where is it? (Gift cards)', 'Balances from an old system by entry or CSV; each gets a new code. Where to find it: Gift cards, Import.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Look up, history, resend and void', 'Look up, history, resend and void: does ServOS do this and where is it? (Gift cards)', 'Find a card and manage it. Where to find it: Gift cards, Look up.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'All gift cards', 'All gift cards: does ServOS do this and where is it? (Gift cards)', 'Every card by status, source, batch and search. Where to find it: Gift cards, All gift cards.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Gift card settings and branding', 'Gift card settings and branding: does ServOS do this and where is it? (Gift cards)', 'Minimum, maximum, expiry, and company wide card art with per site override. Where to find it: Gift cards, Settings; Appearance, Gift cards.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Gift card shop', 'Gift card shop: does ServOS do this and where is it? (Gift cards)', 'Customers buy a card online for themselves or email it to someone. Where to find it: /gift; Gift cards, Online purchases.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Gift card balance check', 'Gift card balance check: does ServOS do this and where is it? (Gift cards)', 'A public page to check a balance by code. Where to find it: /gift/balance.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Any gift code looks up', 'Any gift code looks up: does ServOS do this and where is it? (Gift cards)', 'The till and Back Office look up any 16 letter or digit code, so imported cards are found. Where to find it: Till and Back Office gift card lookup.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Sell gift cards at the POS', 'Sell gift cards at the POS: does ServOS do this and where is it? (Gift cards)', 'A Gift button under Orders when gift cards are on; pick an amount, pay by any tender, then load a physical card or print a new one, or later from History. Money in, not sales: no VAT, discount, loyalty or service charge, its own line in every report and Xero. Where to find it: POS left bar.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Blank cards for the POS', 'Blank cards for the POS: does ServOS do this and where is it? (Gift cards)', 'Bulk create prints codes worth nothing until a sale loads them, made 20 at a time with progress. Where to find it: Gift cards, Bulk create.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Online gift cards on Adyen', 'Online gift cards on Adyen: does ServOS do this and where is it? (Gift cards)', 'The gift page takes card and wallets in page and settles to the venue''s own Adyen store; a card is issued only on a verified payment. Where to find it: /gift.', 'Customers, loyalty and marketing / Gift cards', false, false),
('doc', 'servos-features-2026-11-15', 'Forms', 'Forms: does ServOS do this and where is it? (Forms)', 'Up to 12 fields (names, email, phone, birthday, free text, drop down, tick box), your own marketing tick, button and thank you words, for one venue or the company; submissions newest first with Export CSV. Where to find it: Customers, Forms.', 'Customers, loyalty and marketing / Forms', false, false),
('doc', 'servos-features-2026-11-15', 'Every sender in Customers', 'Every sender in Customers: does ServOS do this and where is it? (Forms)', 'Found by phone or email or added, never twice; a ticked box is recorded as consent with the words they saw. Where to find it: Customers.', 'Customers, loyalty and marketing / Forms', false, false),
('doc', 'servos-features-2026-11-15', 'Forms on any website', 'Forms on any website: does ServOS do this and where is it? (Forms)', 'A Form block in the website builder and an embed code for any other site, working with JavaScript off, in your colours; protected against robots and floods. Where to find it: Website builder; Forms, Embed.', 'Customers, loyalty and marketing / Forms', false, false),
('doc', 'servos-features-2026-11-15', 'Overview', 'Overview: does ServOS do this and where is it? (Reports)', 'Today''s revenue, covers, tables, terminals online and quick links. Where to find it: Back Office, Overview.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'All reports', 'All reports: does ServOS do this and where is it? (Reports)', 'Catalogue with search, pins, recents, period picker on the venue clock and business day, server and source filters. Where to find it: Reports, All reports.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Daily trading (P&L)', 'Daily trading (P&L): does ServOS do this and where is it? (Reports)', 'Per day forecast, net sales, VAT out, labour target vs rota vs timesheets, COGS and overhead. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Business summary', 'Business summary: does ServOS do this and where is it? (Reports)', 'Period stats with compare chips and a net to gross ladder. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Daily trend and item sales trend', 'Daily trend and item sales trend: does ServOS do this and where is it? (Reports)', 'Revenue, covers, average check and tips per business day; items by day. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Product mix', 'Product mix: does ServOS do this and where is it? (Reports)', 'Items, categories, modifiers and 86''d items by time of day. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Menu engineering', 'Menu engineering: does ServOS do this and where is it? (Reports)', 'Stars, Plow Horses, Puzzles and Dogs. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Order types and order sources', 'Order types and order sources: does ServOS do this and where is it? (Reports)', 'Channel mix and sales by till, kiosk, online, QR and each delivery platform. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Daypart', 'Daypart: does ServOS do this and where is it? (Reports)', 'Hour by weekday heatmap. Where to find it: Reports, Sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Server scorecard', 'Server scorecard: does ServOS do this and where is it? (Reports)', 'Tip percent, discount rate, void rate and rank per server. Where to find it: Reports, Staff.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Tips report and pooling', 'Tips report and pooling: does ServOS do this and where is it? (Reports)', 'Total tips, cash vs card, per server and a pool calculator. Where to find it: Reports, Tips.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Payroll report', 'Payroll report: does ServOS do this and where is it? (Reports)', 'Closed pay runs with wages plus tips and a BACS CSV. Where to find it: Reports, Staff, Payroll.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Shifts report', 'Shifts report: does ServOS do this and where is it? (Reports)', 'Business day shifts with per server sessions, CSV. Where to find it: Reports, Staff, Shifts.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Exceptions audit', 'Exceptions audit: does ServOS do this and where is it? (Reports)', 'Every void, discount and refund with who did it and who approved. Where to find it: Reports, Exceptions & discounts.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'X report and Z report', 'X report and Z report: does ServOS do this and where is it? (Reports)', 'X prints the day so far from the till; Z prints at every cash up and in Back Office as thermal or PDF with tax by rate. Where to find it: Till functions; Reports, Fiscal, Z report.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Tax summary', 'Tax summary: does ServOS do this and where is it? (Reports)', 'Tax per rate and order type from the same engine as the till. Where to find it: Reports, Fiscal.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Payments and cash, drawer sessions', 'Payments and cash, drawer sessions: does ServOS do this and where is it? (Reports)', 'Payment method breakdown and every cash in and out with variance. Where to find it: Reports, Fiscal.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Transactions and refunds', 'Transactions and refunds: does ServOS do this and where is it? (Reports)', 'All closed checks with search, item detail and refunds. Where to find it: Reports, Order reports.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Open orders, Tables and Bookings reports', 'Open orders, Tables and Bookings reports: does ServOS do this and where is it? (Reports)', 'Live unpaid tables; revenue and turns per table; covers, no shows, package attach rate and CSV. Where to find it: Reports, Order reports.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'KDS performance', 'KDS performance: does ServOS do this and where is it? (Reports)', 'Average, p50 and p90 bump time by station and hour. Where to find it: Reports, Kitchen.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Loyalty report', 'Loyalty report: does ServOS do this and where is it? (Reports)', 'Overview, top members, transactions and stamp card activity, every row counted. Where to find it: Reports, Loyalty.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Tables Ready insights', 'Tables Ready insights: does ServOS do this and where is it? (Reports)', 'Parties, seated, average wait, quote accuracy, no shows. Where to find it: Reports, Tables Ready.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Location compare', 'Location compare: does ServOS do this and where is it? (Reports)', 'Every venue side by side on its own clock with outlier alerts. Where to find it: Reports, Multi location.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Sites control on every report', 'Sites control on every report: does ServOS do this and where is it? (Reports)', 'Tick All sites or any mix of your company''s sites next to the period buttons; 17 reports add the sites together, item reports use each site''s own menu, Tax summary uses each site''s VAT. Where to find it: Back Office, Reports.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'All sites overview', 'All sites overview: does ServOS do this and where is it? (Reports)', 'Every site in your company, one block per currency, a Change column per site and a like for like group line. Replaces Location compare. Where to find it: Back Office, Reports, All sites overview.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Sales mix', 'Sales mix: does ServOS do this and where is it? (Reports)', 'Sales split into groups such as Food, Drinks and Other with share, change, quantity and average price; Set up groups maps your top level categories; a mix strip on Business summary and Z report; gift cards are their own group. Where to find it: Back Office, Reports, Sales mix.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'One percent rule', 'One percent rule: does ServOS do this and where is it? (Reports)', 'The change chip is the same everywhere and says what it compares to (Today compares to the same weekday last week up to the same time of day). Where to find it: Reports and the Owner app.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Every sale counted', 'Every sale counted: does ServOS do this and where is it? (Reports)', 'A report over more than about 1,000 sales no longer stops at the newest 1,000. Hour by hour charts draw real bars; KDS performance shows station names and plain words for Typical and 9 in 10 by. Where to find it: Back Office, Reports.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Reports align to the P&L', 'Reports align to the P&L: does ServOS do this and where is it? (Reports)', 'Every report uses the Daily trading rule: net sales without VAT, tips or service, refunds off on the day made, labour from approved timesheets, one waste source. Demo history is left out everywhere and says so. Where to find it: every report, the Owner and Manager apps.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'One revenue ladder', 'One revenue ladder: does ServOS do this and where is it? (Reports)', 'Item sales, less voids, discounts, rewards and refunds, to net sales and Money collected. The same on Business summary, the Z report and the till''s X and Z slips, to the penny with the Owner app. Where to find it: Reports; Till functions.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Booking payments and Bookings reports', 'Booking payments and Bookings reports: does ServOS do this and where is it? (Reports)', 'Every booking payment with its status and what is owed back; Bookings rebuilt with several sites, covers by service, booking money and lead sources. Where to find it: Reports.', 'Money and reporting: reports, close day, cash, tax, Xero / Reports', false, false),
('doc', 'servos-features-2026-11-15', 'Shift', 'Shift: does ServOS do this and where is it? (Shifts, close day and cash)', 'Current shift, drawer status, recent shifts; a manager closes once every drawer is cashed up. Where to find it: Reports, Shifts.', 'Money and reporting: reports, close day, cash, tax, Xero / Shifts, close day and cash', false, false),
('doc', 'servos-features-2026-11-15', 'Close day', 'Close day: does ServOS do this and where is it? (Shifts, close day and cash)', 'Cash up each drawer then close the day with totals by payment method and tax. Where to find it: Reports, Close day.', 'Money and reporting: reports, close day, cash, tax, Xero / Shifts, close day and cash', false, false),
('doc', 'servos-features-2026-11-15', 'Petty cash ledger', 'Petty cash ledger: does ServOS do this and where is it? (Shifts, close day and cash)', 'Float, cash sales, drops, expenses and adjustments with a running balance per drawer. Where to find it: Reports, Petty cash.', 'Money and reporting: reports, close day, cash, tax, Xero / Shifts, close day and cash', false, false),
('doc', 'servos-features-2026-11-15', 'Accounting day', 'Accounting day: does ServOS do this and where is it? (Shifts, close day and cash)', 'One venue business day and one per tender sum shared by every report, the apps and Xero; refunds land on the day made. Where to find it: Behind every report; day start in Location settings.', 'Money and reporting: reports, close day, cash, tax, Xero / Shifts, close day and cash', false, false),
('doc', 'servos-features-2026-11-15', 'Tax rates', 'Tax rates: does ServOS do this and where is it? (Tax)', 'The venue''s own rates, default and apply to all products. Where to find it: Menu, Tax & VAT.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'Tax profiles (US)', 'Tax profiles (US): does ServOS do this and where is it? (Tax)', 'Stacked state, county, city and per unit lines, compounding, rounding, order type scope, tax basis, service and delivery switches, assigned per venue, category or item. Where to find it: Tax & VAT, Tax profiles.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'VAT on discounted bills', 'VAT on discounted bills: does ServOS do this and where is it? (Tax)', 'VAT recorded on what was charged on every channel. Where to find it: Automatic.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'VAT follows the item rule', 'VAT follows the item rule: does ServOS do this and where is it? (Tax)', 'Every sale books the VAT of each item''s own Back Office tax rule, on every channel (till, kiosk, QR, online, phone, bar tabs, delivery apps). A till or kiosk that has not loaded its VAT rates refuses to take payment and says so. The server books VAT itself for QR and online orders. Where to find it: automatic.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'Nightly VAT check', 'Nightly VAT check: does ServOS do this and where is it? (Tax)', 'Every morning ServOS re checks yesterday''s sales at every venue against the item rules and names any sale whose VAT does not match. Where to find it: ServOS admin.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'Service charge never carries VAT', 'Service charge never carries VAT: does ServOS do this and where is it? (Tax)', 'On every channel; Xero posts it with no VAT and Back Office offers only a no VAT rate for it. Where to find it: automatic.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'VAT on deals by line', 'VAT on deals by line: does ServOS do this and where is it? (Tax)', 'A deal on some lines takes VAT off those lines'' own rates, and a part refund gives back the VAT of the items refunded. Where to find it: automatic.', 'Money and reporting: reports, close day, cash, tax, Xero / Tax', false, false),
('doc', 'servos-features-2026-11-15', 'Xero connection', 'Xero connection: does ServOS do this and where is it? (Xero)', 'Connect this venue to its own Xero organisation. Where to find it: Settings, Xero (accounting).', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Push sales to Xero', 'Push sales to Xero: does ServOS do this and where is it? (Xero)', 'Each business day as Receive Money per clearing account and Spend Money for refunds; dry run; auto post nightly. Where to find it: Xero, Push sales.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Account mapping with VAT per rate', 'Account mapping with VAT per rate: does ServOS do this and where is it? (Xero)', 'Map accounts and match each tax rate to a Xero rate. Where to find it: Xero, Account mapping.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Supplier bills to Xero', 'Supplier bills to Xero: does ServOS do this and where is it? (Xero)', 'A posted invoice becomes a Xero bill with the image attached. Where to find it: Purchasing, Invoices.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Daily sales invoice', 'Daily sales invoice: does ServOS do this and where is it? (Xero)', 'One paid sales invoice per site per day, the way Lightspeed did it. Each site has its own Xero contact and invoice numbers (SOS-LEEDS-20260929), sales lines by group, VAT by rate, card and cash as payments into clearing accounts. Where to find it: Back Office, Xero, VAT and accounts.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Copy my Lightspeed setup and Check figures', 'Copy my Lightspeed setup and Check figures: does ServOS do this and where is it? (Xero)', 'Reads the accounts and tracking already in your Xero and fills the mapping; Check figures shows exactly what one day would post before anything is sent. Where to find it: Back Office, Xero.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Postings', 'Postings: does ServOS do this and where is it? (Xero)', 'Every day, every site, what was sent and a link to open it in Xero. A day that went the old way (bank transactions) can be replaced with the daily invoice (2 Oct). Where to find it: Back Office, Xero, Postings.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Two organisations, one sign in', 'Two organisations, one sign in: does ServOS do this and where is it? (Xero)', 'A Xero login that can see two companies stores the organisation chosen on Xero''s screen; the Connection tab shows which organisation a site posts to and lets you pick another; a different Xero login can never move a site. Where to find it: Back Office, Xero, Connection.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Refunds on the day''s invoice', 'Refunds on the day''s invoice: does ServOS do this and where is it? (Xero)', 'A refund is a minus line starting with Refund on the invoice of the day it was made, with its VAT. A day Xero cannot take that way still posts as invoice plus credit note. Where to find it: automatic.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Card fees line', 'Card fees line: does ServOS do this and where is it? (Xero)', 'Card fees go on each day''s invoice as one minus line, Card fees, no VAT, so the card payment matches what Adyen pays out. Create a Card fees account from Back Office or pick one. A day waits up to 16 hours for a fee that has not arrived. Where to find it: Back Office, Xero, VAT and accounts, Payments.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'VAT hold', 'VAT hold: does ServOS do this and where is it? (Xero)', 'A day with a sale that has no VAT is held and never posted at VAT 0; Postings says which sale. Where to find it: Back Office, Xero, Postings.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Month end stock journal', 'Month end stock journal: does ServOS do this and where is it? (Xero)', 'The closing stock journal for each legal company goes to Xero as a draft when you press Send, only once. Invoices lock once sent to Xero, with the site on every line. Where to find it: Reports, Stock and GP, Month end pack.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Credit notes to Xero', 'Credit notes to Xero: does ServOS do this and where is it? (Xero)', 'A credit note recorded in Purchasing, Credits goes to Xero as a supplier credit note, one net line on the purchases account with the site tracking, supplier matched or created, the scan attached, and set against the bill it answers when that bill is in Xero. Each credit note shows In Xero, Failed with Retry, or Send to Xero. Sent once only. Where to find it: Purchasing, Credits.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Bills and credit notes sent by themselves', 'Bills and credit notes sent by themselves: does ServOS do this and where is it? (Xero)', 'A switch, Send bills and credit notes automatically: from the moment it is on, a posted supplier invoice and an added credit note go to Xero within fifteen minutes, never anything older than the switch. A refused one is tried again after two hours, six times at most. Where to find it: Xero, Connection.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Bills and credit notes card', 'Bills and credit notes card: does ServOS do this and where is it? (Xero)', 'Everything sent, failed or sending in the last 60 days with Open in Xero links and Retry on a failure. Where to find it: Xero, Postings.', 'Money and reporting: reports, close day, cash, tax, Xero / Xero', false, false),
('doc', 'servos-features-2026-11-15', 'Stock overview', 'Stock overview: does ServOS do this and where is it? (Stock and purchasing)', 'Stock value, setup checklist, needs attention and a live movement feed. Where to find it: Back Office, Inventory, Overview.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Stock items', 'Stock items: does ServOS do this and where is it? (Stock and purchasing)', 'Purchased and made items with units, conversions, packs and live pack to unit cost. Where to find it: Inventory, Stock items.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Stock counts and par levels', 'Stock counts and par levels: does ServOS do this and where is it? (Stock and purchasing)', 'Walk the shelf, see variance, approve; par per item. Where to find it: Inventory, Stock counts.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Wastage', 'Wastage: does ServOS do this and where is it? (Stock and purchasing)', 'Log waste against stock or a menu item with reason, off stock at cost; also from the till. Where to find it: Inventory, Wastage; Till functions, Record waste.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Stock reports', 'Stock reports: does ServOS do this and where is it? (Stock and purchasing)', 'Valuation, recipe GP, movements, The Gap, by supplier, all CSV. Where to find it: Inventory, Reports.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Recipes', 'Recipes: does ServOS do this and where is it? (Stock and purchasing)', 'Dish recipes with live cost and GP per order type; prep sub recipes with yield. Where to find it: Produce, Recipes.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Batches', 'Batches: does ServOS do this and where is it? (Stock and purchasing)', 'Production runs with planned vs actual yield, lot and expiry. Where to find it: Produce, Batches.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Suppliers', 'Suppliers: does ServOS do this and where is it? (Stock and purchasing)', 'Contacts, terms, delivery days, minimum and cut off. Where to find it: Purchasing, Suppliers.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Order pad', 'Order pad: does ServOS do this and where is it? (Stock and purchasing)', 'Suggested quantities from usage, delivery days and par; one order per supplier. Where to find it: Purchasing, Order pad.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Purchase orders', 'Purchase orders: does ServOS do this and where is it? (Stock and purchasing)', 'Create, email the supplier, receive line by line with delivery note prices. Where to find it: Purchasing, Orders.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Invoices with OCR', 'Invoices with OCR: does ServOS do this and where is it? (Stock and purchasing)', 'Snap an invoice, Claude reads the lines, match, post to stock and cost. Where to find it: Purchasing, Invoices.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Price changes', 'Price changes: does ServOS do this and where is it? (Stock and purchasing)', 'Every cost movement per stock item so creeping prices show. Where to find it: Purchasing, Price changes.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Below par and 86 list for managers', 'Below par and 86 list for managers: does ServOS do this and where is it? (Stock and purchasing)', 'Items 86''d or below par by supplier and batch cook status. Where to find it: Manager app, Kitchen tab.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Stock off every sale, every channel', 'Stock off every sale, every channel: does ServOS do this and where is it? (Stock and purchasing)', 'The database takes stock off each booked sale once: till, reader, kiosk, online, QR, catering, pay at table, MPOS, HubRise and ezCater, within about a minute. Every venue is on it from day one. Where to find it: automatic; Stock control shows waiting sales.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Refunded food is waste', 'Refunded food is waste: does ServOS do this and where is it? (Stock and purchasing)', 'A refund, or a void after the kitchen made it, is booked as waste. Only items set Can go back on the shelf return to stock. Where to find it: Stock items, Can go back on the shelf.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Stock areas', 'Stock areas: does ServOS do this and where is it? (Stock and purchasing)', 'Cellar, Walk in fridge, Freezer, Dry store, Bar and Kitchen, each holding its own quantity; deliveries land in the receiving area. Where to find it: Inventory, Stock areas.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Counts by area, supplier or spot check', 'Counts by area, supplier or spot check: does ServOS do this and where is it? (Stock and purchasing)', 'Grouped by area, each counter marks their area complete. Counts while trading work each line from the moment it was counted. Approved counts are locked; a manager PIN approves. Where to find it: Inventory, Stock counts.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Opening stock and cost source', 'Opening stock and cost source: does ServOS do this and where is it? (Stock and purchasing)', 'The first count books Opening stock at a real cost. Each venue picks cost from the price list or from deliveries. Where to find it: Stock control, Overview, Cost here.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Transfers', 'Transfers: does ServOS do this and where is it? (Stock and purchasing)', 'Move stock between areas, or send it to another venue of your company. The cost travels with it; what did not arrive is booked as Short on transfer. Where to find it: Inventory, Transfers.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Order from the full supplier list', 'Order from the full supplier list: does ServOS do this and where is it? (Stock and purchasing)', 'A new purchase order lists every item the supplier sells with pack, price, on hand, on order, par and suggested packs, with search and filters, built for a thousand items. Where to find it: Purchasing, Orders.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Receive a delivery on the phone', 'Receive a delivery on the phone: does ServOS do this and where is it? (Stock and purchasing)', 'Type what came or tap All as ordered, or photograph the delivery note to match the lines; enter the temperature; over 8 C it becomes Reject delivery. Where to find it: Manager app, Kitchen.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Raise order and count on the phone', 'Raise order and count on the phone: does ServOS do this and where is it? (Stock and purchasing)', 'Raise order uses the Back Office pack and price. Count stock or log waste by area with the barcode; figures are kept on the phone first so a dropped signal loses nothing. Where to find it: Manager app, Kitchen.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Stock below zero shown', 'Stock below zero shown: does ServOS do this and where is it? (Stock and purchasing)', 'Valued at nothing, tagged red with the figure and named under Needs attention. Where to find it: Inventory, Overview and Reports.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Allergens and calories from recipes', 'Allergens and calories from recipes: does ServOS do this and where is it? (Stock and purchasing)', 'Each supplier item holds allergens, may contain, diets and nutrition. Recipes show them with a Checked button, and the till, kiosk, online, QR, catering, booking page, menu boards, print menu and HubRise read them. Show calories adds kcal. Where to find it: Produce, Recipes; Location settings, Show calories.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Recipe cards', 'Recipe cards: does ServOS do this and where is it? (Stock and purchasing)', 'On the till, the kitchen screen and the Manager app, at that venue only, with no costs. Where to find it: Till item info, kitchen screen, Manager app.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Waste never refused', 'Waste never refused: does ServOS do this and where is it? (Stock and purchasing)', 'A menu product with no recipe is still recorded as waste, with the lost sale. Where to find it: Till functions, Record waste; Inventory, Wastage.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'Duplicate invoices stopped', 'Duplicate invoices stopped: does ServOS do this and where is it? (Stock and purchasing)', 'A second invoice with the same number from the same supplier is refused, and an invoice for an order just received is kept as its paperwork. Where to find it: Purchasing, Invoices.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'US units', 'US units: does ServOS do this and where is it? (Stock and purchasing)', 'Gallons, quarts, pints, cups and fl oz at US sites, imports read US units, the invoice reader reads US invoices as dollars with month first dates, purchase sales tax stays in the cost, supplier emails use the venue''s money and dates. UK units unchanged. Where to find it: Stock items, Invoices, Order pad.', 'Stock and purchasing', false, false),
('doc', 'servos-features-2026-11-15', 'One company stock list', 'One company stock list: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'One list of items, categories and suppliers for every site, with a Sites column. Tick items to add them to sites, set par, change prices or pause. A one site company sees no change. Where to find it: Inventory, Stock items.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Site picker', 'Site picker: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'All sites, a group of sites or one site on Inventory, Produce and Purchasing. Where to find it: top of each stock screen; Location settings, Site groups.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Item page with a Sites tab', 'Item page with a Sites tab: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Details, Packs, Suppliers, Sites, Used in and Changes. Per site: supplier, price, par, area, counted, purchased or made. Where to find it: Stock items, an item.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Shared suppliers, packs and prices', 'Shared suppliers, packs and prices: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'One supplier list with each site''s account number, order email, minimum, delivery days and order by times; Change prices, Import price list, Pause at sites. Where to find it: Purchasing, Suppliers.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Import and Copy a site', 'Import and Copy a site: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Import a CSV or a Nory or MarketMan export with a check screen first; Copy a site sets up a new site from an old one. Where to find it: Stock items.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Who can change what', 'Who can change what: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Stock control on the Team screen: Their sites, Their sites full control, or All sites. Anyone else sees a lock line with Suggest a change. Where to find it: Back Office, Team.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Company recipes', 'Company recipes: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'One recipe list with a Recipe missing tab. Each recipe has Details, Ingredients, Sites, Allergens and nutrition, Recipe card and Changes; Make sizes, Swap an ingredient, Clone. Where to find it: Produce, Recipes.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Batch and prep', 'Batch and prep: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Bought in, Made here or Made to order per site; a Prep list with Done ticks; batch and PPDS labels. Where to find it: Produce, Batch and prep.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Purchasing screens', 'Purchasing screens: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Due to order, Forecast, Deliveries, Credits and Budgets. The Order pad shows the order by time, a weekly budget bar, the minimum order and Order for many sites. Where to find it: Purchasing.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Approvals and standing orders', 'Approvals and standing orders: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'An order over the supplier limit waits for another manager or head office. Standing orders, bank holidays and no delivery days. Where to find it: Purchasing, Orders.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Invoice inbox and credits', 'Invoice inbox and credits: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Upload supplier invoices into the inbox; each is matched to its order and delivery and can be split across sites. A price above the agreed price raises a credit request. Where to find it: Purchasing, Invoices, Credits.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Count plans and End of day', 'Count plans and End of day: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Count plans and templates with a shelf order, a second approval over a limit, locked periods, and an End of day close down for fresh food. Waste over the limit needs a manager PIN. Where to find it: Inventory, Stock counts.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Transfer requests', 'Transfer requests: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'A site asks another for stock and the sender fulfils or refuses; a receiver can dispute; lot and use by ride on each line. Where to find it: Inventory, Transfers.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Central kitchen', 'Central kitchen: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Production plan, Orders in, Ingredients needed, Pick and send with a delivery note and labels, and monthly recharges to Xero. Where to find it: Produce, Central kitchen; Manager app.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Stock and GP dashboard', 'Stock and GP dashboard: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Sales, GP actual and theoretical, the gap, comps, purchases and stock value; a league of every site in red, amber or green against your targets. Where to find it: Reports, Stock and GP.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Head office stock reports', 'Head office stock reports: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Every site side by side or the company total: stock value with in transit, movement, theoretical against actual, cost of sales and GP, product GP, waste, purchases, price paid, days on hand, par, off contract, budget, transfers, count compliance and the month end pack. Compare, export and share a link. Where to find it: Reports, Stock and GP.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Weekly stock email', 'Weekly stock email: does ServOS do this and where is it? (Multi site stock (companies with more than one site))', 'Every Monday head office gets the company pack and each site manager their own site. Where to find it: email.', 'Stock and purchasing / Multi site stock (companies with more than one site)', false, false),
('doc', 'servos-features-2026-11-15', 'Workforce dashboard and Staff records', 'Workforce dashboard and Staff records: does ServOS do this and where is it? (People: workforce)', 'HR record per person: contract, sections, pay, NI, emergency contact, bank details, holiday, onboarding, POS user, Staff app invite. Where to find it: Back Office, Workforce.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Rota', 'Rota: does ServOS do this and where is it? (People: workforce)', 'Weekly grid by section with clash checks, publish and labour target tiles. Where to find it: Workforce, Rota.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Build with AI (AI rota)', 'Build with AI (AI rota): does ServOS do this and where is it? (People: workforce)', 'Proposes shifts within hours, leave, max days in a row and rest, from a learned 8 week forecast. Where to find it: Rota, Build with AI.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Timesheets', 'Timesheets: does ServOS do this and where is it? (People: workforce)', 'Punches and manual entries, edit, approve, Clock out now. Where to find it: Workforce, Timesheets.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Payroll', 'Payroll: does ServOS do this and where is it? (People: workforce)', 'Pay runs with approved hours plus tronc, bank details and BACS CSV; closed runs locked. Where to find it: Workforce, Payroll.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Time off and availability', 'Time off and availability: does ServOS do this and where is it? (People: workforce)', 'Requests, approvals, holiday as an accrual ledger, weekly availability. Where to find it: Workforce, Time off & availability.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Onboarding and signing', 'Onboarding and signing: does ServOS do this and where is it? (People: workforce)', 'Offer letter, Right to Work, e sign contract, bank details, POS access. Where to find it: Workforce, Onboarding; /sign/<token>.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Compliance vault', 'Compliance vault: does ServOS do this and where is it? (People: workforce)', 'Required documents per person with expiry traffic lights. Where to find it: Workforce, Compliance.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Training', 'Training: does ServOS do this and where is it? (People: workforce)', 'Modules with tasks and deadlines, assigned by position or person, done in the Staff app. Where to find it: Workforce, Training.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Positions and rates', 'Positions and rates: does ServOS do this and where is it? (People: workforce)', 'Role rate card with future dated changes. Where to find it: Workforce, Positions & rates.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Tronc and tips', 'Tronc and tips: does ServOS do this and where is it? (People: workforce)', 'Weekly pool split by hours and role points to the penny. Where to find it: Workforce, Tronc / tips.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Announcements', 'Announcements: does ServOS do this and where is it? (People: workforce)', 'Message everyone, a section or a role in app and by SMS; shown on the Time Clock. Where to find it: Workforce, Announcements.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Workforce settings', 'Workforce settings: does ServOS do this and where is it? (People: workforce)', 'Labour target, accrual rate, pay period, sections with minimum cover, max days, minimum rest. Where to find it: Workforce, Workforce settings.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Geofenced clock in', 'Geofenced clock in: does ServOS do this and where is it? (People: workforce)', 'Venue pin and radius; the server refuses a punch outside the fence; Staff app only. Where to find it: Workforce settings, geofence card.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Time Clock app', 'Time Clock app: does ServOS do this and where is it? (People: workforce)', 'A tablet by the staff door to clock in, out and break with a PIN. Where to find it: ServOS Time Clock app; paired under Hardware, Terminals.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Staff app', 'Staff app: does ServOS do this and where is it? (People: workforce)', 'Shifts, news, timesheets, training tasks and clock in on the phone. Where to find it: ServOS Staff app.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Tamper evident audit', 'Tamper evident audit: does ServOS do this and where is it? (People: workforce)', 'Approvals, time off, clock outs, purchase orders, tronc and payroll chained in an audit log. Where to find it: Behind Workforce and the Manager app.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Open shifts', 'Open shifts: does ServOS do this and where is it? (People: workforce)', 'Put a shift on the rota with nobody on it. When published, everyone in that position who can take it gets a text and can claim it in the staff app. Where to find it: Rota, Add an open shift.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Shift swaps', 'Shift swaps: does ServOS do this and where is it? (People: workforce)', 'Can''t do this shift in the staff app offers it to everyone in the position or to one colleague. With approval on, claims wait on the Rota and in the Manager app. The server checks position, overlap, leave and hours. Where to find it: Staff app; Workforce settings, Shift claims and swaps.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'My availability', 'My availability: does ServOS do this and where is it? (People: workforce)', 'Staff set Available, Preferred or Unavailable for each weekday; managers see it on the rota. Where to find it: Staff app, Me.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'US sites in Workforce', 'US sites in Workforce: does ServOS do this and where is it? (People: workforce)', 'A USD venue gets dollars, US dates and times, SSN last 4, Form I-9 and W-4, twice monthly pay periods, a US payroll export with overtime over 40 hours, and US federal holidays. Where to find it: automatic from the venue currency.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'US phone numbers', 'US phone numbers: does ServOS do this and where is it? (People: workforce)', '801 555 1234 texts +1 801 555 1234 at a US venue. Where to find it: rota texts, announcements, shift texts.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Pay premiums', 'Pay premiums: does ServOS do this and where is it? (People: workforce)', 'Extra pay for weekend, bank holiday and night hours. Payroll, rota cost and timesheets all use it; where two apply the higher one wins. Where to find it: Workforce settings, Pay premiums.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'US overtime across sites', 'US overtime across sites: does ServOS do this and where is it? (People: workforce)', 'Hours at every linked site count toward one 40 hour week; the site that crosses 40 holds the overtime, at half the week''s blended rate; payroll shows hours at other sites and the premium; the US export carries both. Where to find it: Workforce, Payroll.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Overtime in every labour report', 'Overtime in every labour report: does ServOS do this and where is it? (People: workforce)', 'Daily trading, the Owner and Manager apps, Stock and GP and the rota''s actual cost add the overtime premium the database keeps on each timesheet. Where to find it: Reports; Rota.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Tip credit overtime', 'Tip credit overtime: does ServOS do this and where is it? (People: workforce)', 'Staff paid below the minimum wage get overtime worked out on the minimum wage; a Minimum wage setting, federal $7.25 when blank. Where to find it: Workforce settings.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Positions with no overtime', 'Positions with no overtime: does ServOS do this and where is it? (People: workforce)', 'Exempt positions earn no overtime and do not count toward 40; salaried positions start ticked. Where to find it: Workforce settings.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Health cover hours (ACA)', 'Health cover hours (ACA): does ServOS do this and where is it? (People: workforce)', 'Hours a month at every site, 130 hours full time, and the company''s full time plus equivalents against the 50 of a large employer. Where to find it: Workforce, Payroll (US venues).', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Why open shifts are hidden', 'Why open shifts are hidden: does ServOS do this and where is it? (People: workforce)', 'The staff app says why an open shift is not offered (another position, already started). Where to find it: Staff app, Shifts.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Head office staff', 'Head office staff: does ServOS do this and where is it? (People: workforce)', 'Off by default; on adds a Head office tick and an Annual salary to each person. A head office person is paid their salary each pay period with no timesheets, cannot clock in (the till and staff app say so), is not on the rota, takes no open shifts, lands in no site''s labour, and shows on the Owner app company card as its own Head office line. Someone who also covers shifts at a site keeps a normal linked record there. UK and US. Where to find it: Workforce settings, Head office staff; Staff.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'US paid time off (PTO)', 'US paid time off (PTO): does ServOS do this and where is it? (People: workforce)', 'Off until switched on. Hourly staff earn 1 hour for every 30 worked (or your number) from approved timesheets when you press Run accrual, with an optional yearly most. Balances, requests, approvals, the staff app and payroll work as for UK holiday; UK venues still accrue 12.07%. Where to find it: Workforce settings at a US venue, Paid time off.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'US state break rules', 'US state break rules: does ServOS do this and where is it? (People: workforce)', 'Pick your state (California, Oregon, Washington, Colorado, Nevada, New York, Illinois, Massachusetts and more), no state rule, or your own; the setting says what the rule asks. Timesheets, the rota and the Manager app flag a missing meal break against your state, and the clock out auto deduct uses it as the floor. Where to find it: Workforce settings at a US venue, State break rules.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'California daily overtime and meal premium', 'California daily overtime and meal premium: does ServOS do this and where is it? (People: workforce)', 'Time and a half over 8 hours in a day, double time over 12, weekly over 40 counting only hours not already daily overtime; one hour at the regular rate when a needed meal break was short. Payroll shows Double time and Meal premium and the US export carries both. Where to find it: Payroll at a California venue.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Tip credit top up (US)', 'Tip credit top up (US): does ServOS do this and where is it? (People: workforce)', 'A server paid below the minimum wage must reach it each work week with their tips; when cash wage plus tips kept falls short, payroll adds the difference as Tip top up, never averaged across weeks. Hover a figure for the week''s hours, owed, paid and tips. Where to find it: Payroll, Tip top up; US payroll export.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Cash tips at clock out (US)', 'Cash tips at clock out (US): does ServOS do this and where is it? (People: workforce)', 'The Time Clock and the staff app ask Cash tips this shift at clock out; type the amount or tap No cash tips. Timesheets show them, Payroll has a Cash tips (declared) column, reported for tax and never added to what you pay; declared cash tips count toward the tip credit top up. Where to find it: Time Clock, Staff app, Timesheets, Payroll.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Private data behind one door', 'Private data behind one door: does ServOS do this and where is it? (People: workforce)', 'ID numbers, bank details, identity document files (passports, visas, I-9 papers) and pay rate overrides are seen only by owners, admins and logins given Can see payroll details, enforced in the database. Everyone else sees Hidden, a save never wipes a hidden number, a manager still sees the document row and its expiry and their own site''s rates. The Manager app no longer sends anyone''s hourly rate. Where to find it: Team, Can see payroll details; Staff records.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Workforce dashboard Today view', 'Workforce dashboard Today view: does ServOS do this and where is it? (People: workforce)', 'Who is on shift now, rostered today, late or no show, hours so far against plan, planned wage cost, what is waiting (time off requests, onboarding, expiring documents, open shifts) and the week. Real data only, never sample numbers. Where to find it: Workforce, Dashboard.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Blocked periods for time off', 'Blocked periods for time off: does ServOS do this and where is it? (People: workforce)', 'First day, last day and a reason shown to staff. The staff app shows the blocks above the request form and refuses a holiday, PTO or unpaid leave request on a blocked day in words; sick and parental leave always go through; a manager filing in Back Office sees the block in red and can still file. Where to find it: Workforce, Time off, Leave, Blocked periods.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Availability changes from the next rota period', 'Availability changes from the next rota period: does ServOS do this and where is it? (People: workforce)', 'A change in the staff app never touches a week already on the rota; it is filed for the week after the last published week, the app says the date, and the pending change shows under the current one. The rota, clash warnings, open shifts and the AI builder read the pattern in effect for the date they look at. Where to find it: Staff app, My availability; Back Office, Availability.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'No sample positions', 'No sample positions: does ServOS do this and where is it? (People: workforce)', 'A new site starts with no positions and Positions and rates shows Add role; the nine UK sample positions are no longer written into a venue. Untouched samples already written were removed. Where to find it: Workforce, Positions and rates.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Hours a week on salaried positions only', 'Hours a week on salaried positions only: does ServOS do this and where is it? (People: workforce)', 'The week on a position only turns a salary into an hourly rate, so it shows for Salaried positions only; hourly positions carry no week and hours live on the person''s contract. Where to find it: Positions and rates.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Your contracts first (UK)', 'Your contracts first (UK): does ServOS do this and where is it? (People: workforce)', 'The venue''s own contract templates are listed first and preselected; the built in UK contract is last and never offered at a US venue. Where to find it: Onboarding and signing.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'US pay rules', 'US pay rules: does ServOS do this and where is it? (People: workforce)', 'US tip pools leave out managers, supervisors and exempt positions and pool no service charge; PTO off means approved time off deducts nothing; age banded positions pay their rate; the leaver dialog and PTO words follow US law; payroll columns add up to Total. Where to find it: Payroll and Tronc and tips at a US venue.', 'People: workforce', false, false),
('doc', 'servos-features-2026-11-15', 'Team chat', 'Team chat: does ServOS do this and where is it? (Team chat)', 'A Chat tab in the staff app. Venue groups are made by themselves, plus direct messages, groups, photos, replies, reactions, edits, @mentions and mute. Where to find it: Staff app, Chat.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Groups and announcements', 'Groups and announcements: does ServOS do this and where is it? (Team chat)', 'Managers make groups, position groups and announcement groups where only admins post. Mark an announcement Urgent and see who has seen it. Where to find it: Staff app; Back Office, Workforce, Team chat.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Chat in Back Office', 'Chat in Back Office: does ServOS do this and where is it? (Team chat)', 'A Chats tab to read and send in your groups and direct messages; New messages anyone in the company. Owners are in every venue group. Where to find it: Workforce, Team chat, Chats.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Moderation and word filter', 'Moderation and word filter: does ServOS do this and where is it? (Team chat)', 'A word filter in English and Spanish (Standard, Strict or Custom) refuses blocked words, card numbers and bank details. An automatic check flags bullying for a manager. Reports to check: hide, keep or mute. Where to find it: Workforce, Team chat; Manager app, Chat.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Private messages stay private', 'Private messages stay private: does ServOS do this and where is it? (Team chat)', 'An owner can read a direct message only with a typed reason, which is logged. Where to find it: Team chat, Read a private message.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Push notifications', 'Push notifications: does ServOS do this and where is it? (Team chat)', 'Every message pings phones by default, with no Firebase. Urgent announcements also go by text to anyone not reached. Quiet when off shift is a switch for each person. Where to find it: Staff app, Me; Team chat, Settings, Notifications.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Unread counts and chat bell', 'Unread counts and chat bell: does ServOS do this and where is it? (Team chat)', 'A count on each chat with For you and Mentions you marks; a chat bell on every Back Office page; @names highlighted. Where to find it: Staff app; Back Office top bar.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Chat settings', 'Chat settings: does ServOS do this and where is it? (Team chat)', 'Who makes groups, direct message rules, filter level, how long messages are kept, and a text backup for urgent posts. Where to find it: Team chat, Settings.', 'People: workforce / Team chat', false, false),
('doc', 'servos-features-2026-11-15', 'Also works at', 'Also works at: does ServOS do this and where is it? (One person at several sites)', 'Add a person at any number of other sites (Select all) with each site''s position and pay rate, from Workforce or Team. Where to find it: Workforce, Staff, Sites; Team, Sites.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Link and unlink', 'Link and unlink: does ServOS do this and where is it? (One person at several sites)', 'Records or till users made by hand at two sites are suggested (same name, email or mobile) and joined with Link; Unlink makes them one site again. Where to find it: Sites.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Shared PIN and card', 'Shared PIN and card: does ServOS do this and where is it? (One person at several sites)', 'The same PIN, card and sign in method at every site, changed once for all; a PIN used by someone else at any of their sites is refused with the name; own details follow them; till role, permissions, position and rate stay per site. Where to find it: Team.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Managers of every site only', 'Managers of every site only: does ServOS do this and where is it? (One person at several sites)', 'Linking, adding a site or changing a shared PIN needs access to every site involved, so a manager of one site can never sign in at another. Where to find it: automatic.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Rota across sites', 'Rota across sites: does ServOS do this and where is it? (One person at several sites)', 'A shift overlapping their shift at another site is refused (add, copy, copy week, build with AI); the other site''s shift shows faintly; their name shows hours elsewhere and US overtime. Where to find it: Workforce, Rota.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Staff app and open shifts across sites', 'Staff app and open shifts across sites: does ServOS do this and where is it? (One person at several sites)', 'Shifts from every site with the site name; a claim overlapping another site or over the most hours a week is refused. Where to find it: Staff app, Shifts.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Joins by itself', 'Joins by itself: does ServOS do this and where is it? (One person at several sites)', 'A Workforce record made later for a linked till user (first clock in, Set up on the POS) joins the person. Where to find it: automatic.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Clock in follows the shift', 'Clock in follows the shift: does ServOS do this and where is it? (One person at several sites)', 'Someone with shifts at more than one site is clocked in at the site of the shift they are on, from 60 minutes before it starts, with that site''s location check, pay rate and rules. No shift: the app asks which site (Allow or Refuse per site). One open shift at a time, with Clock out there offered. Timesheets, announcements and training from every site, each named. Where to find it: Staff app, Clock in; Workforce settings, Clock in without a shift.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Primary location for holiday and PTO', 'Primary location for holiday and PTO: does ServOS do this and where is it? (One person at several sites)', 'Holiday or PTO earned at every site goes into one balance, taken and paid at the primary location only. Only someone with access to every site the person works at can change it; approving a request filed elsewhere moves it to the primary location first. Where to find it: Workforce, Staff, a person, Sites.', 'People: workforce / One person at several sites', false, false),
('doc', 'servos-features-2026-11-15', 'Compliance overview', 'Compliance overview: does ServOS do this and where is it? (Operations and compliance)', 'Live KPI strip, unit status and recent breaches. Where to find it: Back Office, Operations, Compliance.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Temperature units', 'Temperature units: does ServOS do this and where is it? (Operations and compliance)', 'Fridges, freezers and probes with thresholds and schedules. Where to find it: Operations, Temperature.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Checklists', 'Checklists: does ServOS do this and where is it? (Operations and compliance)', 'Opening, closing and cleaning templates with photo sign off. Where to find it: Operations, Checklists.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Prep schedule', 'Prep schedule: does ServOS do this and where is it? (Operations and compliance)', 'Scheduled batch cooks recorded in the Manager app. Where to find it: Operations, Prep schedule.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Maintenance', 'Maintenance: does ServOS do this and where is it? (Operations and compliance)', 'Raise, assign and resolve; breaches raise them automatically. Where to find it: Operations, Maintenance.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Alert rules and escalation', 'Alert rules and escalation: does ServOS do this and where is it? (Operations and compliance)', 'Severity, SMS and email, recipients, ladder every 5 minutes; food safety never suppressed. Where to find it: Operations, Alert rules.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Compliance calendar', 'Compliance calendar: does ServOS do this and where is it? (Operations and compliance)', 'EHO ready month view of every round, breach and action, CSV. Where to find it: Operations, Calendar.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Documents', 'Documents: does ServOS do this and where is it? (Operations and compliance)', 'Certificates and policies up to 20 MB, archive never delete. Where to find it: Operations, Documents.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Forms', 'Forms: does ServOS do this and where is it? (Operations and compliance)', 'Build your own forms such as an Accident book; completed forms list with print and CSV. Where to find it: Operations, Forms.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Operations tablet', 'Operations tablet: does ServOS do this and where is it? (Operations and compliance)', 'Temperature rounds, checklists, goods in checks, maintenance, alerts, documents and forms. Where to find it: ServOS Operations app; Operations, Devices.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'Checklist photos on a tablet', 'Checklist photos on a tablet: does ServOS do this and where is it? (Operations and compliance)', 'Adding a photo to a checklist task works again on a paired Operations tablet, and a photo that cannot be saved says so in plain words. Where to find it: Ops tablet and the Manager app''s Ops tab.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'SOPs', 'SOPs: does ServOS do this and where is it? (Operations and compliance)', 'Tick This is an SOP on a document (Back Office or the Operations tablet) and its words are read out of the PDF or photo at upload and kept; an existing document can be made or unmade an SOP and the list shows a badge. Word files are refused, save as PDF first. Where to find it: Operations, Documents.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'FDA Food Code at US venues', 'FDA Food Code at US venues: does ServOS do this and where is it? (Operations and compliance)', 'Temperatures in Fahrenheit (cold hold 41F, hot hold 135F, deliveries rejected above 45F), the 9 major allergens, the FDA calorie statement and US ID types for the age check. UK unchanged. Where to find it: Checklists and temperature logs at a US venue.', 'Operations and compliance', false, false),
('doc', 'servos-features-2026-11-15', 'AI Assistant', 'AI Assistant: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Ask about sales, items, servers, tables, payments, menu, stock and POS health; write actions need your confirmation. Where to find it: Back Office, Settings, AI assistant; AI mode on the till.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Manager app', 'Manager app: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Home, Reports, Team with approvals and Clock out, Ops and Kitchen with stock to order and raise purchase order. Where to find it: ServOS Manager app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Owner app', 'Owner app: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Read only rollup across every venue: sales vs forecast, labour percent, live orders, week vs last week, top items. Where to find it: ServOS Owner app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Location switcher', 'Location switcher: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Switch Back Office between the venues your login can access. Where to find it: Back Office, bottom left.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Activity feed', 'Activity feed: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Bell and panel on the till with urgent payment notes and alerts. Where to find it: Till, activity feed bell.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Owner app periods and reports', 'Owner app periods and reports: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Today, This week and This month at the top; every card follows the choice (net sales, forecast for the same days, orders); tap a venue or the group card for seven reports (sales by hour, week by day, payment mix, order types and channels, discounts voids and refunds, top items, labour). Days follow each site''s business day and a US site shows in dollars. Where to find it: Owner app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Food, Drinks, Other bar', 'Food, Drinks, Other bar: does ServOS do this and where is it? (Owner and manager tools, AI)', 'A sales mix bar on every venue card and the group card, with the change in share in points. Where to find it: Owner app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Manager app on iPad', 'Manager app on iPad: does ServOS do this and where is it? (Owner and manager tools, AI)', 'The app uses the whole screen with the tabs in a rail down the left; in landscape Home, Reports, Team and Kitchen show two panels side by side; larger pairing and PIN screens; nothing being typed is lost when the iPad turns. Phones unchanged. Where to find it: Manager app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Try the demo', 'Try the demo: does ServOS do this and where is it? (Owner and manager tools, AI)', 'A No venue yet? Try the demo button on the Manager app''s pairing screen links the phone to your demo venue with no Back Office step; the staff PIN still guards the data. Where to find it: Manager app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Assistant printing check', 'Assistant printing check: does ServOS do this and where is it? (Owner and manager tools, AI)', 'The shift assistant no longer reports a print agent as down (no venue runs one); it reports tickets that have waited over 10 minutes to print. Where to find it: AI assistant.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Net and Gross switch', 'Net and Gross switch: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Every figure in the Owner app follows it and says Including or Excluding VAT, after refunds. Where to find it: Owner app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Stock on the Owner app', 'Stock on the Owner app: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Each venue card has a Stock line (value, GP, gap, waste, last count) and the venue screen a Stock card, once the venue holds stock. Where to find it: Owner app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Manager app stock tabs', 'Manager app stock tabs: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Transfers, Shop buy, End of day and Forecast; at a central kitchen also Orders in, Production plan and Pick and send. Where to find it: Manager app.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Manager app clock out on iPhone and iPad', 'Manager app clock out on iPhone and iPad: does ServOS do this and where is it? (Owner and manager tools, AI)', 'The question sits in the row with the PIN box. Where to find it: Manager app, Team.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Stock counts that cannot connect say so', 'Stock counts that cannot connect say so: does ServOS do this and where is it? (Owner and manager tools, AI)', 'After 20 seconds the area list or count sheet says so with Try again. Where to find it: Manager app, Stock.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Recipe cards on iPad', 'Recipe cards on iPad: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Full width product buttons, sizes named with their product (Latte Large), cards open from the paired device. Where to find it: Manager app, Recipe cards.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Assistant answers from your SOPs', 'Assistant answers from your SOPs: does ServOS do this and where is it? (Owner and manager tools, AI)', 'What is our SOP for a spill is answered in the SOP''s own words, steps in order, naming the SOP; no SOP and it says so and lists the ones that exist; it never invents a step. Where to find it: AI assistant on the till and in Back Office.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Assistant on the venue clock', 'Assistant on the venue clock: does ServOS do this and where is it? (Owner and manager tools, AI)', 'Today, the hour buckets and the Back Office greeting run on the venue''s clock, not the laptop''s. Where to find it: AI assistant.', 'Owner and manager tools, AI', false, false),
('doc', 'servos-features-2026-11-15', 'Adyen only', 'Adyen only: does ServOS do this and where is it? (Platform, security and integrations)', 'Every Stripe and Ryft screen and function is gone and Adyen is the default everywhere; old Stripe and Ryft bills stay readable and a refund on one says to use that processor''s dashboard. Where to find it: everywhere.', 'Platform, security and integrations', false, false),
('doc', 'servos-features-2026-11-15', 'Second step for Back Office', 'Second step for Back Office: does ServOS do this and where is it? (Sign in security)', 'Face ID, Touch ID, fingerprint, passkey or authenticator code after the password; 30 minute idle sign out. Where to find it: Settings, Sign in security.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Passkeys', 'Passkeys: does ServOS do this and where is it? (Sign in security)', 'Fingerprint, face or Windows Hello, several per person, never remove the last way in. Where to find it: Sign in security.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Lost phone reset', 'Lost phone reset: does ServOS do this and where is it? (Sign in security)', 'An owner resets staff, ServOS resets an owner; team list shows who has no second step. Where to find it: Sign in security; Admin portal.', 'Platform, security and integrations / Sign in security', true, false),
('doc', 'servos-features-2026-11-15', 'Device and venue fences', 'Device and venue fences: does ServOS do this and where is it? (Sign in security)', 'Paired devices write only to their own venue, each tab keeps its venue, the anon key cannot rewrite venue rows. Where to find it: Server side on every write.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Face ID inside the ServOS apps', 'Face ID inside the ServOS apps: does ServOS do this and where is it? (Sign in security)', 'Passkeys work inside the iPad and iPhone apps (ServOS POS build 8, ServOS Owner build 6 and later), not only in Safari. Older app builds keep the emailed code. Where to find it: the app''s sign in.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Passkey on the Owner sign in', 'Passkey on the Owner sign in: does ServOS do this and where is it? (Sign in security)', 'The Owner app''s sign in offers Sign in with a passkey, as Back Office does. Where to find it: Owner app.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Why there is no passkey', 'Why there is no passkey: does ServOS do this and where is it? (Sign in security)', 'When a device cannot offer a passkey the sign in page says why and where to switch it on (for an iPad: Settings, General, AutoFill & Passwords). Where to find it: sign in pages.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Sign ups closed', 'Sign ups closed: does ServOS do this and where is it? (Sign in security)', 'Nobody can make an account on their own until ServOS has self sign up; kiosk, online, QR, gift and catering sessions keep working. Where to find it: automatic.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Demo logins skip the second step', 'Demo logins skip the second step: does ServOS do this and where is it? (Sign in security)', 'A login linked only to demo venues (for App Store review) is not asked for the second step. Where to find it: automatic.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Demo login loads its figures', 'Demo login loads its figures: does ServOS do this and where is it? (Sign in security)', 'The App Store reviewer''s demo login was let in and then refused by the data functions; the functions now ask the same rule as the sign in screen, so all three layers agree. Real logins unchanged. Where to find it: Owner app, demo account.', 'Platform, security and integrations / Sign in security', false, false),
('doc', 'servos-features-2026-11-15', 'Company Admin', 'Company Admin: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Organisations, locations and users with access per location. Where to find it: Admin portal.', 'Platform, security and integrations / Admin portal (ServOS staff)', true, false),
('doc', 'servos-features-2026-11-15', 'Get this venue taking cards', 'Get this venue taking cards: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Six numbered steps from Adyen account to Apple Pay, found by venue code, Turn on live asks you to type LIVE. Where to find it: Admin, Processing.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Processing list', 'Processing list: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'One row per venue with region, environment, Linked, Holder, KYC and Payouts. Where to find it: Admin, Processing.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Card rates per payment type', 'Card rates per payment type: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Six rows percent plus pence with platform defaults and per venue overrides, written to Adyen split rules. Where to find it: Admin, Processing, Card rates.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Recheck KYC with Adyen', 'Recheck KYC with Adyen: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Asks Adyen again for the venue''s verification state. Where to find it: Admin, Processing.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Register for Apple Pay and web addresses', 'Register for Apple Pay and web addresses: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'One button registers origins and shop domains. Where to find it: Admin, step 4.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Revenue and Check a payment', 'Revenue and Check a payment: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Card volume, commission, SaaS fees and platform revenue per month and venue; where every penny of one payment went. Where to find it: Admin, Revenue.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'FranPOS residuals', 'FranPOS residuals: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'What FranPOS owes each month on their card account, with the invoice. Where to find it: Admin, FranPOS.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Monthly plan and add ons', 'Monthly plan and add ons: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Monthly total, additional devices, HubRise add on per venue. Where to find it: Admin, Processing, plan.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Provision location', 'Provision location: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Mirrors a new venue into the platform database so loyalty, gift cards and online ordering work. Where to find it: Automatic.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Overnight watchdog', 'Overnight watchdog: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Runs every 5 minutes on GitHub with a read only token, counts stranded payments and failures, opens an issue and can text. Where to find it: GitHub Actions.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Email an update', 'Email an update: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Write a what''s new in plain text, pick the companies, see exactly who will get it and send; a test to yourself first. Where to find it: ServOS admin, Messages and emails.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Faster payouts switch', 'Faster payouts switch: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Go live step 5 says how fast a venue is paid out (fast, same day, or regular, 1 to 2 working days) with a Faster payouts switch; UK venues are set up fast from now on. Where to find it: ServOS admin, go live, Payouts.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'FranPOS residuals', 'FranPOS residuals: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'The screen loads again; only live money counts (test environment payments are never read); marking an invoice sent, paid or void reports a database error as itself. Where to find it: ServOS admin, FranPOS residuals and Revenue.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Starter plan and US prices', 'Starter plan and US prices: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Starter at 99 GBP replaces Free for new UK venues. US venues pay in dollars: Starter 149, Growth 299, Full 399 USD. Venues on Free stay as Free (old plan). Revenue keeps currencies apart. Where to find it: Admin, Processing, Plan; Admin, Revenue.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Create user finds existing logins', 'Create user finds existing logins: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Looks the email up directly, links the profile and sets the password, and says what it did. Where to find it: Admin, Create user.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Delete organisation, all locations and wipe all data', 'Delete organisation, all locations and wipe all data: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'One screen counts first what would go (locations, rows by table, closed checks, customers, logins, files), asks for the organisation name typed out, then deletes everything on the server venue by venue, each step all or nothing, through every table''s own fence; a step that fails stops and says so and Delete again carries on. Never a ServOS staff login. The location Delete uses the same screen. Where to find it: Company Admin, Organisations, Delete organisation.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'Update emails: removed and unsubscribed', 'Update emails: removed and unsubscribed: does ServOS do this and where is it? (Admin portal (ServOS staff))', 'Every person in Email an update has a Remove button and a Removed from emails card with Put back; every update email carries an Unsubscribe link and the headers Gmail and Outlook use, and pressing it removes that address by itself. Back Office logins are not affected. Where to find it: Company Admin, Email an update.', 'Platform, security and integrations / Admin portal (ServOS staff)', false, false),
('doc', 'servos-features-2026-11-15', 'AI needs a signed in user', 'AI needs a signed in user: does ServOS do this and where is it? (Data and AI safety)', 'The AI assistant, AI rota and menu import refuse anyone not signed in to that venue; the till''s assistant uses its paired device. Where to find it: automatic.', 'Platform, security and integrations / Data and AI safety', false, false),
('doc', 'servos-features-2026-11-15', 'Staff record links locked', 'Staff record links locked: does ServOS do this and where is it? (Data and AI safety)', 'Only a company owner, past the second step, can link a till user to a staff record. Every change is in the Workforce audit log. Where to find it: Workforce, a person''s record, Set up on the POS.', 'Platform, security and integrations / Data and AI safety', false, false),
('doc', 'servos-features-2026-11-15', 'Stock and bookings fenced', 'Stock and bookings fenced: does ServOS do this and where is it? (Data and AI safety)', 'Stock moves only by that venue''s devices, its logins or ServOS; bookings cannot be made with the bare public key; the invoice scan checks who is asking. Where to find it: automatic.', 'Platform, security and integrations / Data and AI safety', false, false),
('doc', 'servos-features-2026-11-15', 'Messages by venue staff only', 'Messages by venue staff only: does ServOS do this and where is it? (Data and AI safety)', 'Only staff of the venue, or an owner of its company, can change its message templates. Where to find it: Back Office, Messages.', 'Platform, security and integrations / Data and AI safety', false, false),
('doc', 'servos-core-2026-11-18', 'Staff app for team members', 'Is there a staff app for team members to download from the App Store or Play Store, or is ServOS only web based? How do staff see rotas and clock in on their phone?', 'Yes, staff have the ServOS Staff app: shifts and rota, timesheets, clock in, holiday and availability, shift swaps, training and team chat. It works on any phone today: open app.serv-os.app/?mode=staff in the phone browser, sign in with the email and password from the staff invite, then use Add to Home Screen so it opens like an app. Android: the ServOS Staff app can also be downloaded directly from https://tinyurl.com/233ga5kz (it is not on the Google Play Store yet, so the phone may ask to allow installs from the browser). iPhone: the Staff app is not on the App Store yet, so use the browser and Add to Home Screen. Managers send the invite from Back Office, Workforce, the person''s staff record.', 'Apps and devices', false, true),
('doc', 'servos-core-2026-11-18', 'Which ServOS apps are on the App Store', 'Which ServOS apps can I download from the App Store or Google Play? Is there an iPad or iPhone app?', 'On the Apple App Store today: ServOS POS (https://apps.apple.com/gb/app/servos-pos/id6805131080) and ServOS KDS kitchen screen (https://apps.apple.com/gb/app/servos-kds/id6805150003). The other apps (Staff, Manager, Owner, Time Clock, Kiosk, Waitlist and Bookings) run in any browser at app.serv-os.app and are on their way to the stores. On Android they can be downloaded directly from a link the team can send; they are not on Google Play yet.', 'Apps and devices', false, true),
('doc', 'servos-core-2026-11-18', 'Is ServOS just a web app', 'Is ServOS just a web app? Does it need to be installed? What devices does it run on?', 'ServOS is a cloud system: the same live data on the till, kitchen screens, kiosks, phones and Back Office. It runs on ServOS tills and card readers, iPads (ServOS POS and KDS are on the App Store), Android devices and any browser. Back Office is at app.serv-os.app in any browser. Staff, managers and owners each have their own app (Staff, Manager, Owner) that works in the phone browser and can be added to the home screen.', 'Apps and devices', false, true),
('doc', 'servos-core-2026-11-18', 'Owner and Manager apps', 'Is there an app for owners or managers to see sales, approve shifts and check the venue on their phone?', 'Yes. The Owner app (sales, labour and the numbers across your sites) and the Manager app (today''s trading, rota, approvals and stock) both work in the phone browser: app.serv-os.app/?mode=owner and app.serv-os.app/?mode=manager. Sign in, then Add to Home Screen. Android download links: Owner https://tinyurl.com/2yeddrv8 and Manager https://tinyurl.com/28lz2epj (not on Google Play yet).', 'Apps and devices', false, true),
('doc', 'servos-core-2026-11-18', 'Time Clock app', 'How do staff clock in and out? Is there a clock in app or tablet?', 'Staff clock in on the till with their PIN, on a Time Clock tablet, or in the Staff app on their phone (the Staff app checks they are at the venue when geofenced clock in is on). The Time Clock runs at app.serv-os.app/?mode=clock on any tablet; on Android it can be downloaded from https://tinyurl.com/278wvz92.', 'Apps and devices', false, true);
