-- Support chat knowledge (ticket 1035, 18 Nov 2026). Safe to run twice:
-- it replaces only its own rows (servos-features-2026-11-15, servos-core-2026-11-18).
-- Needs migration 127 first (search index + kb_search).
begin;
delete from public.kb_docs where source = 'doc' and source_ref in ('servos-features-2026-11-15', 'servos-core-2026-11-18');
commit;
select source_ref, count(*), count(*) filter (where internal_only) staff_only from public.kb_docs where source = 'doc' group by 1;
